programs.sol:
"""A boundary-sensitive lexical response, plus the final digit of year-like numbers.

At a document's beginning, English articles and code declarations are strongly
negative; word fragments and non-Latin writing are usually positive. Grammatical
classes, word frequency and word shape approximate the remaining lexical variation.
An uninterrupted repetition of the first token keeps that boundary response.
Away from the beginning, predict zero except on the fourth digit of a date-like
number (strongest around the late twentieth and early twenty-first centuries).
"""
import unicodedata
from functools import lru_cache
import regex
import wordnet
from wordfreq import zipf_frequency

READS = ()

# Corrections for familiar grammatical classes: unspaced and space-prefixed forms.
GRAMMAR = [
    ('and or but nor yet', -.78, -2.29),  # coordination
    ('of to', -.33, -3.54),  # nominal/infinitival linkers
    ('in on at for by from with into onto over under through between among about as',
     -2.32, -1.70),  # prepositions
    ('if while when where because although though unless until since whether than',
     -4.19, -1.59),  # subordinators
    ('i me you he him she her it we us they them', -1.35, -.28),
    ('my your his its our their', -1.74, -1.99),
    ('this that these those', -5.16, -1.76),
    ('am is are was were be been being', -2.18, -1.48),
    ('do does did have has had', -2.54, -1.42),
    ('can could will would shall should may might must cannot', -2.19, -2.97),
    ('no not never', -1.31, -1.32),
    ('what who which whose why how', -5.72, -1.62),
    ('all any some each every both either neither many much few more most other another',
     -.66, -.61),
]
GRAMMAR = [(frozenset(words.split()), a, b) for words, a, b in GRAMMAR]

# Bare lowercase declaration keywords at the beginning of source code.
DECLARATIONS = [
    ('package', -29.8),                    # package declaration
    ('import', -23.5),                     # import statement
    ('const', -13.8),                      # constant declaration
    ('def from', -11.6),                   # Python definition/import
    ('using namespace module export', -9.7),  # namespace/module declarations
    ('class interface struct enum function int var', -7.7),
]
DECLARATIONS = [(frozenset(words.split()), v) for words, v in DECLARATIONS]


@lru_cache(maxsize=20000)
def beginning(s):
    w = s.strip()
    low = w.lower()
    space = s.startswith(' ')
    if s == '<|im_start|>':
        return -.53
    if s == '\r':
        return -10.6
    if s.isspace():
        return (-.71 if len(s) == 1 else -5.9) if not w and set(s) == {' '} else .2
    if w and set(w) == {'·'}:
        return -4.23  # typographic dot leaders
    if w.isascii() and w.isdigit():
        return -2.44 if w == '0' else 1.25
    if regex.fullmatch(r'\p{Latin}+', w):
        if s == w:
            for words, value in DECLARATIONS:
                if w in words:
                    return value
        if low == 'the':
            return -11.85 if space else (-10.49 if w.istitle() else -6.5)
        if low == 'a':
            return -7.61 if space and w.islower() else -6.15
        if low == 'an':
            return -3.2 if space else -2.0
        f = max(0, zipf_frequency(low, 'en') - 3)
        pos = wordnet.parts_of_speech(low)
        value = (.03 - .56*f) if space else (1.35 - .29*f)
        value += (.49 if space else -.34) * w.istitle()
        value -= (.64 if space else .82) * w.isupper()
        value += .23 * (len(w) == 1)
        value += (.47 if space else .38) * ('noun' in pos)
        value -= (.52 if space else 1.07) * ('verb' in pos)
        value -= (.44 if space else .56) * ('adjective' in pos)
        for words, a, b in GRAMMAR:
            if low in words:
                value += b if space else a
        return value
    for script, value in [('Han', 1.7), ('Cyrillic', 1.7), ('Arabic', 1.1),
                          ('Hiragana', .6), ('Katakana', .6)]:
        if regex.search(r'\p{Script=' + script + '}', w):
            return value
    if not w:
        return 0.
    if w.startswith('#'):
        return -8.3 if w == '##' else -4.5
    if w.startswith(('/*', '//')):
        return -2.
    if w == '.':
        return -5.6 if space else .85
    if w == ',':
        return -.8
    if w == '=' and space:
        return -7.
    if w in ('+', '-') and space:
        return -3.5
    if w == ')':
        return -3.2
    if unicodedata.category(w[0]) in ('Ps', 'Pi'):
        return 2.8
    if w in ('"', "'"):
        return 1.2
    if w == '*':
        return 4.5
    return 0.


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        first, initial, repeating, digits = token, beginning(s), True, ''
    else:
        _, first, initial, repeating, digits = carry
        repeating = repeating and token == first
    digits = (digits + s)[-8:] if len(s) == 1 and s in '0123456789' else ''
    value = initial if repeating else 0.
    if not repeating and len(digits) == 4:
        year = int(digits)
        if 1600 <= year <= 2029:
            value = -1.1 * min(1., (year - 1600) / 400) ** 2
        elif 2030 <= year <= 2099:
            value = -.3
    return (doc, first, initial, repeating, digits), float(value)

programs.haiku:
"""Layer-1 MLP down-projection component 5696: a "document-opener" detector.

What it does, in plain terms
- The model reads a document's first token with nothing before it, so this component's
  value there depends only on which word or symbol that token is. Everywhere else in a
  document it is essentially silent (predicted 0).
  Tiers of the value written at a document's first token:
    * -25: file openers of Java/Go/Kotlin-style code: `package`, `import`;
    * -11: other code and query openers (`def`, `from`, `using`, `const`, `void`,
      `public`, `namespace`, `#include`, `SELECT`) and the articles `the` / `The`;
    * -5: other English function words and sentence openers (`a`, `A`, `of`, `to`,
      `and`, `in`, `is`, `This`, `When`, `In`), weaker code words (`class`, `return`,
      `int`), and the markdown/comment marks `#` and `##`;
    * -2: whitespace-only tokens;
    * -1: other words that begin with a space (mid-sentence continuations);
    * +1.5: non-ASCII tokens (CJK, Cyrillic, ...), and +1.3 for lowercase word pieces
      that start without a space;
    * 0: every other token.

Predictions are in the component's own units, (x.V)*||U||.
"""

READS = ()

FILE_OPENERS = {"package", "import"}
CODE_OPENERS = {
    "def", "from", "using", "const", "void", "public", "private", "namespace", "export",
    "bool", "#include", "#ifndef", "#import", "select", "create", "drop", "the",
}
FUNCTION_WORDS = {
    "a", "an", "of", "to", "and", "or", "in", "for", "that", "is", "with", "on", "it",
    "was", "be", "by", "at", "as", "this", "if", "when", "what", "how", "i", "can", "are",
    "not", "has", "have", "which", "#", "##", "class", "function", "module", "int", "var",
    "return", "static", "struct", "#define", "#pragma", "show", "use", "add", "update",
}
VALUE = {
    "file": -25.0, "code": -11.0, "function": -5.0, "space": -2.0, "nonascii": 1.5,
    "spaced_word": -1.0, "lower_piece": 1.3, "other": 0.0,
}


def opener_value(text):
    word = text.strip()
    lower = word.lower()
    if word == "":
        return VALUE["space"]
    if lower in FILE_OPENERS:
        return VALUE["file"]
    if lower in CODE_OPENERS or text in CODE_OPENERS:
        return VALUE["code"]
    if lower in FUNCTION_WORDS:
        return VALUE["function"]
    if not word.isascii():
        return VALUE["nonascii"]
    if text.startswith(" "):
        return VALUE["spaced_word"]
    if text[:1].islower():
        return VALUE["lower_piece"]
    return VALUE["other"]


def step(carry, prefix, upstream):
    new_doc = len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not new_doc:
        return None, 0.0
    return None, opener_value(prefix.token_strings[-1])

programs.sol:
"""Standalone spaces closing padded fields carry a negative response.

Look for extra spacing inside the current line, not indentation. The strongest
case closes an alphanumeric field just after a double or triple space.
Punctuation-attached fields and later words get smaller responses. Uppercase
preceding tokens have a weaker background response without extra spacing.
Non-space tokens and extensions of existing whitespace receive zero. Only
the last 512 characters of the current line are kept, resetting per document.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = 0.0
    if token and not token.strip(' '):
        last_word = re.search(r'\S+$', text)
        if last_word:
            word = last_word[0]
            gaps = 0
            words_after = None
            for gap in re.finditer(r' {2,}(?=\S)', text):
                tail = text[gap.end():]
                if not text[:gap.start()].strip():
                    continue
                gaps += 1
                if len(gap[0]) <= 3:
                    words_after = len(re.findall(r'\S+', tail)) - 1
            if len(token) == 1:
                value = -0.06
                if (len(prefix.token_strings) > 1
                        and prefix.document_ids[-2] == doc):
                    previous = prefix.token_strings[-2]
                    if previous.isupper():
                        value = -1.3 if len(previous) == 1 else -0.3
                if any(c.isalnum() for c in word) and words_after is not None:
                    if words_after == 0:
                        value = -5.1 if word.isalnum() else -2.1
                    elif words_after <= 10:
                        value = -1.15 if gaps <= 2 else -2.2
                    elif gaps:
                        value = -1.0
                elif gaps:
                    if words_after is not None and words_after <= 1:
                        value = -2.5
                    else:
                        value = -1.0
            elif len(token) == 2 and words_after is not None and words_after <= 5:
                before = text[:last_word.start()]
                gap_width = len(before) - len(before.rstrip(' '))
                value = -2.2 if gap_width >= 2 else -0.7
    line = (text + token).rsplit('\n', 1)[-1][-512:]
    return (doc, line), value

"""A coarse determiner-sensitive name/subject and calendar-year signal.

The fourth digit of an 1800--2099 year gets a positive pulse, especially
following a determiner. Dates and prepositional uses get smaller pulses.
Capitalized place/language/month names near determiners also get positive
values. Dictionary science/activity classes and noun-forming endings give
weaker, context-dependent responses; preposition-led uses can be negative.

A short causal text buffer joins subword fragments. These rules leave most
positions near zero, and do not explain token-specific or non-English detail.
"""
import re
from functools import lru_cache
from calendar import month_name
import wordnet

READS = ()
ARTICLES = {'a', 'an', 'the', 'this', 'that', 'these', 'those',
            'my', 'your', 'our', 'his', 'her', 'their', 'its'}
PREPOSITIONS = {'in', 'on', 'at', 'from', 'to', 'by', 'of', 'since',
                'until', 'during', 'through', 'before', 'after'}
MONTHS = frozenset(name.lower() for name in month_name if name)
WORD_DETERMINERS = ARTICLES | {'any', 'each', 'some', 'every', 'other',
                               'another', 'no'}
WORD_PREPOSITIONS = PREPOSITIONS | {'for', 'with', 'without', 'about',
                                   'between', 'into', 'over', 'under'}
NOUN_ENDINGS = ('tion', 'sion', 'ment', 'ness', 'ity', 'ics', 'ism')


@lru_cache(maxsize=65536)
def word_kind(word):
    categories = wordnet.categories(word)
    parts = wordnet.parts_of_speech(word)
    return ('noun.location' in categories, 'verb' in parts,
            wordnet.is_a(word, 'language'), wordnet.is_a(word, 'city'),
            wordnet.is_a(word, 'science'), wordnet.is_a(word, 'sport'),
            'noun.act' in categories, wordnet.is_a(word, 'discipline'))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    text = (old + token)[-120:]
    value = 0.0
    # Calendar years: respond only when the fourth digit arrives.
    number = re.search(r'([0-9]+)$', text)
    if number and token.isascii() and token.isdigit():
        digits = number[0]
        if len(digits) == 4 and 1800 <= int(digits) <= 2099:
            before = text[:number.start()]
            words = re.findall(r'[A-Za-z]+', before.lower())
            last = words[-1] if words else ''
            value = 0.65 if digits.startswith(('19', '20')) else 0.27
            if last in ARTICLES:
                value = 2.2 if digits.startswith(('19', '20')) else 1.1
            elif last in PREPOSITIONS:
                if int(digits) < 1900:
                    value = 0.0
                else:
                    value = 0.2 if digits.startswith('19') else 0.3
            elif last in MONTHS:
                value = 0.52 if int(digits) >= 1900 else 0.22
            # An opening bracket starts a fresh citation rather than a date.
            if before.rstrip().endswith(('(', '[')):
                value = 0.85 if digits.startswith(('19', '20')) else 0.35
    # The unfinished current word is all we know at this position.
    match = re.search(r'[A-Za-z]+$', text)
    if match and token and token[-1].isascii() and token[-1].isalpha():
        word = match[0]
        before = text[:match.start()]
        words = re.findall(r'[a-z]+', before.lower())[-6:]
        det_distance = next((i+1 for i, w in enumerate(reversed(words))
                   if w in WORD_DETERMINERS), 7)
        prep_distance = next((i+1 for i, w in enumerate(reversed(words))
                   if w in WORD_PREPOSITIONS), 7)
        (place, has_verb_sense, language, city, science, sport,
         activity, discipline) = word_kind(word)
        anchored = det_distance < prep_distance and det_distance <= 4
        if word[0].isupper():
            if det_distance <= 2:
                if word.lower() in MONTHS:
                    value = 0.85 if det_distance == 1 else 0.6
                elif len(word) <= 4:
                    value = 0.045
                elif place and not has_verb_sense:
                    value = 0.75 if det_distance == 1 else 0.36
                elif language:
                    value = 0.39
                else:
                    value = 0.14 if token.startswith(' ') else 0.05
            elif prep_distance == 1:
                value = -0.13 if place or discipline else -0.02
            elif city and len(word) > 5:
                value = 0.16
            else:
                value = 0.006
        elif science:
            if anchored:
                value = 0.3 if len(word) > 6 else 0.1
            else:
                value = -0.19 if prep_distance == 1 else 0.0
        elif activity and anchored and len(word) > 7:
            value = 0.7 if sport else 0.075
        elif word.endswith(NOUN_ENDINGS):
            if prep_distance == 1:
                value = -0.075
            else:
                value = 0.075 if det_distance <= 3 else 0.0
        elif len(word) > 9:
            value = 0.05 if det_distance <= 3 else 0.005
        else:
            value = -0.001
    return (doc, text), value

"""A local lexical approximation for 大 (big/great) compounds.

Following 大, approximation words, titles/elder relatives and emphatic
verbs get positive scores. Selected body parts, quantities and size
expressions get negative scores; halls and a few familiar nouns are positive.
After 小 (small), retain half of negative scores only. After Japanese お,
use 27 percent of the score. Unknown combinations get zero, except that
tokens of repeated middle dots get 2. A short UTF-8 tail recognizes split prefixes and
resets at document boundaries. Most small background activations are omitted.
"""
READS = ()

APPROXIMATION = set('約约概慨抵体致旨')
TITLES_AND_ELDERS = set('神仙師师媽妈爺爷叔婶娘')
EMPHATIC_ACTIONS = set('笑秀叫哭喊吼骂罵闹鬧')
BODY_HEAD = {'头', '頭', '口'}
QUANTITIES = {'数', '額', '额', '步', '単', '单'}
HALLS = {'堂', '廳', '厅'}


def completion(word):
    if word in APPROXIMATION:
        return 4.6
    if word in TITLES_AND_ELDERS:
        return 4.5
    if word in EMPHATIC_ACTIONS:
        return 2.2
    if word == '手':
        return -6.6
    if word == '件':
        return -12.0
    if word in BODY_HEAD:
        return -4.8
    if word in {'块', '塊', '隻', '只'}:
        return -6.0
    if word in {'い', 'き', '限'}:
        return -5.4
    if word == '中':
        return -4.0
    if word in QUANTITIES:
        return -3.5
    if word in {'眼', '眼睛', '脚', '腳'}:
        return -2.7
    if word in HALLS:
        return 3.5
    if word in {'坂', '阪', '白'}:
        return 3.8
    if word == '丈夫':
        return 1.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', b''
    else:
        _, previous, tail = carry
    raw = prefix.token_bytes[-1]
    word = raw.decode('utf-8', errors='replace').strip()
    value = 0.0
    if previous.endswith('大'):
        value = completion(word)
    elif previous.endswith('小') and completion(word) < 0:
        value = 0.5 * completion(word)
    elif previous.endswith('お'):
        value = 0.27 * completion(word)
    # A run of middle dots is a separate typographic response.
    if word and set(word) == {'·'} and len(word) >= 2:
        value = 2.0
    tail = (tail + raw)[-12:]
    previous = tail.decode('utf-8', errors='ignore').rstrip()
    return (doc, previous, tail), value

"""Sparse spelling-based approximation, not a complete account of the component.

The main negative responses are to the Indic TTA/DDA/RRA letter series
(and Urdu counterparts), their next two token pieces, Japanese small tsu,
and several Thai vowel/tone continuations. Unicode names identify the letter
series; these are not token-ID lookups. Small script-level offsets and a
separate document-start estimate cover part of the quiet background.
Initial tabs, @@, and an issue-tag boundary have explicit exceptions.

Keep unfinished UTF-8 bytes so a split character can be recognized when it
finishes. All spelling tests concern the current and previous two pieces.
"""
import codecs
import unicodedata as ud
from functools import lru_cache

READS = ()
STOP_NAMES = {'TTA', 'TTHA', 'DDA', 'DDHA', 'RRA', 'TTEH', 'DDAL'}
BASE = {
    'BENGALI': .19,
    'DEVANAGARI': .16,
    'GURMUKHI': .22,
    'MALAYALAM': .12,
    'THAI': .03,
}
STOP_ADJUSTMENT = {
    'DEVANAGARI': -1.58,
    'BENGALI': -.16,
    'MALAYALAM': .44,
    'ARABIC': .12,
}
KANA_STOPS = 'たちつてとだぢづでど'

@lru_cache(maxsize=8192)
def origin(s):
    for c in s:
        if ord(c) > 127 and (c.isalpha() or ud.category(c).startswith('M')):
            return ud.name(c, '').split(' ')[0]
    return ''

@lru_cache(maxsize=8192)
def stop_letter(s):
    return any('LETTER ' in ud.name(c, '') and
               ud.name(c).split('LETTER ')[-1] in STOP_NAMES for c in s)

@lru_cache(maxsize=8192)
def kana(s):
    s = ud.normalize('NFKC', s)
    return ''.join(chr(ord(c)-96) if 'ァ' <= c <= 'ヶ' else c for c in s)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    _, pending, prev, older = (doc, b'', '', '') if first else carry
    data = pending + prefix.token_bytes[-1]
    s, used = codecs.utf_8_decode(data, 'replace', False)
    state = (doc, data[used:], s, prev)

    if first:
        if s == '\t': return state, 1.77
        if s == '@@': return state, 2.32  # a diff hunk header
        value = .15 - .15 * bool(s[:1].isspace())
        if len(s.strip()) == 1 and s.strip().isascii() and s.strip().isalpha():
            value += .23
        return state, value

    language = origin(s)
    value = .002 + BASE.get(language, 0.)
    if len(s) <= 2 and stop_letter(s):
        value -= 1.39
        value += STOP_ADJUSTMENT.get(language, 0.)
        if prev.isspace(): value -= 1.9
    if len(s) <= 3 and len(prev) <= 2 and stop_letter(prev):
        if not s or (not s.isascii() and language == origin(prev)):
            value -= 2.51
            if older.isspace(): value -= 1.77
    if len(s) <= 3 and len(prev) <= 2 and len(older) <= 2:
        if stop_letter(older) and (not s or
                (not s.isascii() and language == origin(older))):
            value -= 1.13
    if any(ud.normalize('NFD', c).lower().startswith(('d\u0323', 't\u0323'))
           for c in s):
        value -= .7  # Latin transliterations with a dot below t or d

    a, b = kana(s), kana(prev)
    if a == 'っ':
        value -= .73
        if b and len(b) <= 2 and b[-1] in KANA_STOPS: value -= 1.02
    if b and len(b) <= 2 and 0 < len(a) <= 2 and b[-1] in KANA_STOPS:
        if a[0] in 'あいうえおーん': value -= .11
    if b == 'ず' and a[:1] in ('つ', 'っ'): value -= .25

    if language == 'THAI':
        if s == '๊': value -= 1.88
        if s == '็' and any(c in prev+older for c in 'เแ'):
            value -= 1.21  # shortener following a preposed vowel
        if s[:1] in ('่', '้') and prev in ('ั', 'ิ', 'ุ', 'ื'):
            value -= .34
        if (prev in ('ท', 'ด', 'ซ') and
                s[:1] in 'าัิีึืุูอ่้๊๋ร' and s != 'ี่'):
            value -= .45
    if prev == 'տ' and s[:1] in 'աեէըիոօու': value -= .47
    if s == 'issue' and prev == '><': value -= 1.25
    return state, float(value)

"""A sparse spelling-and-reading detector, strongest on single Han xiāo forms.

Read completed UTF-8 characters (including split characters), recognize the
Mandarin reading xiāo (excluding silk/walking radicals), and boost 销/銷. Compounds
containing those sale characters get a smaller response. A few secondary
lexical triggers and the Vietnamese rhyme êu have separate responses. A
standalone middle byte in an unfinished E8/E9 Han encoding is negative.
Responses are conservatively scaled by 0.8. This approximates lexical
preferences, not a general classifier of meanings.
"""
import codecs
from functools import lru_cache
from pypinyin import lazy_pinyin, Style
import unihan

READS = ()


@lru_cache(maxsize=4096)
def is_xiao(character):
    # 肖 also has the surname reading xiāo, besides dictionary-default xiào.
    reading = character == '肖' or lazy_pinyin(
        character, style=Style.TONE3
    ) == ['xiao1']
    # Silk and walking-radical homophones did not share the strong response.
    return reading and unihan.radical(character) not in (120, 162)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        pending, tail = b'', ''
    else:
        _, pending, tail = carry

    split = bool(pending)
    data = pending + prefix.token_bytes[-1]
    text, consumed = codecs.utf_8_decode(data, 'ignore', False)
    pending = data[consumed:]
    value = -0.0003
    # Middle byte of a three-byte character in the upper Han ranges.
    if split and len(data) == 2 and len(pending) == 2:
        if data[0] == 0xE8:
            value -= 0.54
        elif data[0] == 0xE9:
            value -= 0.24

    if len(text) == 1:
        if is_xiao(text):
            value += 3.0
            if text in '销銷':
                value += 3.5
            if split:
                value += 5.3
        elif text == '搜':
            value += 3.2
        elif text == '宣':
            value += 2.8
