    'ensure': 4.0,                 # ensuremath
    'hs': 3.7,                    # hspace
    'overs': 5.0, 'unders': 2.9,    # overset, underset
    'phant': 8.4, 'foot': 8.1,      # phantom, footnote / footnotesize
    'include': 7.8, 'use': 3.6,     # includegraphics, usepackage
