     'ref', 'subpackage', 'model'), -5.5))
DOC.update({
    'class': -13.0, 'static': -11.5,
    'return': -1.45, 'returns': -4.7, 'param': 0.3,
    'type': -3.5, 'var': -2.4, 'brief': -1.1,
    'enum': -6.5, 'pre': -5.6,
    'see': -4.6, 'link': -2.3, 'code': -1.8, 'test': -2.5,
    'mock': -1.0, 'suppress': -1.0,
