CONTINUATIONS = {
    ('display', 'style'): 0.5, ('hs', 'pace'): 2.0,
    ('phant', 'om'): 1.2, ('ensure', 'math'): 0.8,
    ('new', 'command'): 0.7, ('eq', 'ref'): 0.6,
