"""A boundary-sensitive, multilingual pulse detector.

The rules approximate chat/reasoning/tool delimiters, negative document-start
pulses, and positive Thai fragments. Thai preposed vowels and broken UTF-8 need
special handling. Smaller rules cover Cyrillic initials, the Thai district
abbreviation อ., Hebrew abbreviation quotes, and Greek question marks.
Ordinary text predicts zero.
These are category averages, not an exact account of context-dependent values.
"""
from functools import lru_cache
import regex
import unicodedata

READS = ()
MARKERS = {
    '</think>': 2.17,
    '<think>': -0.87,
    '<tool_response>': -0.40,
}
THAI_LEADS = (b'\xe0\xb8', b'\xe0\xb9')


@lru_cache(maxsize=60000)
def scripts(s, raw):
    thai = bool(regex.search(r'\p{Script=Thai}', s))
    thai = thai or raw.startswith(THAI_LEADS)
    return (thai, bool(regex.search(r'\p{Script=Greek}', s)),
            bool(regex.search(r'\p{Script=Cyrillic}', s)),
            bool(regex.search(r'\p{Script=Hebrew}', s)))


def predict(s, raw, p, previous_raw, before):
    first = not p or p == '<|endoftext|>'
    if s in MARKERS:
        return MARKERS[s]
    if s == '<tool_call>':
        return 1.16 if before == 'assistant' else 1.63
    if s == '</tool_call>':
        return 1.10 if '"' in p else 1.67
    if s == '</tool_response>':
        return 1.05 if p.strip() in {'.', '!'} else 0.78
    if s == '<|im_start|>':
        return -0.87 if first else -0.24
    if s == '<|im_end|>':
        if p == '</tool_call>':
            return -0.55
        if p == '</tool_response>':
            return -0.43
        if any(c in p.strip()[-3:] for c in '.?!。？！'):
            return 0.78
        return -0.95 if scripts(p, previous_raw)[2] else 0.06
    if s == '\n':
        if p == '<|im_end|>':
            return 0.25 if before.startswith('</tool_') else -0.03
        if p == '<tool_response>':
            return 0.16
        if p == 'assistant' and before == '<|im_start|>':
            return -0.055
    if s == '\n\n' and p in {'<think>', '</think>'}:
        return -0.09 if p == '<think>' else 0.43
    thai, greek, cyrillic, hebrew = scripts(s, raw)
    pt, pg, pc, ph = scripts(p, previous_raw)
    if first and not thai:
        return -0.63 if any(c.isalnum() for c in s) else -0.52
    if s == '.' and p.strip() == 'อ':
        return 11.9  # อ. is a Thai district abbreviation.
    if p.strip() == 'โ' and raw == b'\xc2':
        return 4.9  # Mojibake: this Thai vowel followed by a UTF-8 lead byte.
    if thai:
        if p.strip() == 'เ' and len(s.strip()) == 1:
            return 4.8
        if p.isspace() and len(s) == 1 and s.isalpha():
            return 2.8
        if s[:1].isspace():
            return 1.85
        if raw.startswith(THAI_LEADS) and s == '�':
            return 2.7
        if s.strip() == 'โ':
            return 2.8
        if s.strip() in {'เ', 'แ', 'ใ', 'ไ'}:
            return 1.4
        if all(unicodedata.category(c).startswith('M') for c in s):
            return 0.95
        return 1.0 if len(s.strip()) == 1 else 0.45
    if previous_raw.startswith(THAI_LEADS) and raw[:1] and raw[0] & 192 == 128:
        return 2.1  # Completing a Thai character split across tokens.
    if pt and s == ' ':
        return 1.4
    if pt and s in {'”', '"', '’'}:
        return 4.0
    if pg and s.rstrip('\n') == ';':
        return -3.3
    if pc and s == '.' and len(p.strip()) == 1:
        if p[:1].isspace() or p.isupper():
            return 1.75
    if ph and s in {'"', '״'} and len(p.strip()) == 1:
        return 6.5
    if hebrew and s[:1].isspace() and len(s.strip()) == 1:
        return 1.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        p, previous_raw, before = '', b'', ''
    else:
        _, p, previous_raw, before = carry
    s, raw = prefix.token_strings[-1], prefix.token_bytes[-1]
    value = predict(s, raw, p, previous_raw, before)
    return (doc, s, raw, p), float(value)

"""A coarse orthographic and split-UTF-8 predictor, not a semantic detector.

Ordinary tokens stay near zero. At document starts, number, whitespace,
script and casing give a baseline; x and code punctuation have small offsets.
Bare continuation bytes have a small odd/even bias. Larger corrections mark
two unfinished CJK ranges, completed double-struck letters, and a dot above.
A table of additional individual glyphs added very little in held-out scoring,
so it is omitted. Most of this component's variation remains unexplained.
"""
import unicodedata
import regex

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    tail = b'' if first else carry[1]
    b = prefix.token_bytes[-1]
    s = prefix.token_strings[-1].strip()
    joined = tail + b
    carry = (doc, joined[-3:])
    value = 0.0025

    if first:
        if s.isdigit():
            value = 0.20
        elif b.isspace():
            value = 0.16
        elif regex.search(r'\p{Script=Han}', s):
            value = -0.22
        elif s.istitle() and not s.isupper():
            value = -0.14
        elif s.isupper():
            value = 0.067
        elif s.islower():
            value = 0.048
        else:
            value = -0.03
    elif s == 'x':
        value = -0.08
    elif s and set(s) <= set('_`|\\'):
        value = 0.04

    if not first and len(b) == 1 and 0x80 <= b[0] < 0xc0:
        value = 0.015 + 0.04 * (b[0] & 1)
        if joined.endswith(b'\xe6\xb2'):
            # An unfinished character in the water-radical range U+6C80..6CBF.
            value = -0.86
        elif joined.endswith(b'\xe6\xae'):
            # The U+6B80..6BBF range includes the death-radical characters.
            value = -1.2
        else:
            ch = joined.decode('utf-8', errors='replace')[-1:]
            name = unicodedata.name(ch, '') if ch else ''
            if 'DOUBLE-STRUCK' in name and ch.isalpha():
                value = 1.2
            elif unicodedata.normalize('NFD', ch).endswith('\u0307'):
                # The dot alone, or canonically composed with a letter.
                value = -1.0
    return carry, value

"""Recognize the opening fields of square/curly-bracket structures.

Early list separators are negative, especially the first one. Opening quoted
fields are positive, more strongly on a new line. Reference-link attributes,
Rust attributes and template directives have their own small syntax rules.
Bracketed status/expansion labels and DOCUMENTATION tags are recognized
separately. Other text is assigned zero; this is not a full parser.
Only the last 96 characters are retained, with a reset for each document.
