import re

READS = ()


def response(s, recent):
    text = re.sub(r'\\+([nt])',
                  lambda m: '\n' if m[1] == 'n' else '\t', recent)
    if s == 'ATION' and re.search(r'</?DOCUMENT$', text):
        return 6.0
    if s == ' More' and text.endswith('(View'):
        return -7.0
    if s == ' more' and text.endswith('[Read'):
        return -3.5

    k = max(text.rfind('['), text.rfind('{'))
    if k < 0:
        return 0.0
    body, opener = text[k + 1:], text[k]
    if any(c in body for c in ']}'):
        return 0.0
    field = body.strip()
    token = s.strip()

    if opener == '{':
        if s == 'ref' and not field:
            return 4.5
        if s == '-type' and body == 'ref':
            return 1.2
        if s == '="' and re.fullmatch(r'[a-z]+(?:-[a-z]+)*', body):
            return 2.4
        if field == '%':
            if token == 'set':
                return -3.5
            if token == 'if':
                return -1.4
        if s == ';' and field in ('get', 'get; set'):
            return -3.5 if field == 'get' else -0.6
    else:
        if not field and token in ('Source', 'Reason'):
            return 3.0
        if s == ' type' and field == 'Source':
            return -3.0
        if s == ':' and field == 'Source type':
            return -1.6
        if s == ' working' and field == 'Current':
            return -0.65

    # Numeric or identifier fields, not prose or key:value assignments.
    parts = body.split(',')
    first = parts[0].strip()
    if opener == '[':
        first = first.lstrip('(')  # A list may begin with a tuple.
    numeric = bool(re.fullmatch(r'[-+]?\d+(?:\.\d+)?', first))
    name = bool(re.fullmatch(r'[\w.]+', first))
    if s == ',' and (numeric or name) and len(first) <= 24:
        strength = 1.65 if numeric and opener == '[' else 1.25
        decay = 0.24 if numeric or opener == '{' else 0.08
        return -strength * decay ** (len(parts) - 1)
    if s == ';' and opener == '[' and (numeric or name):
        return -2.5
    if s == ' ' and opener == '[' and numeric and len(parts) == 1:
        return -1.8

    # A quote may share its token with a variable/key sigil.
    quote = token.lstrip('\\').rstrip('_$') in ("'", '"')
    # Listing line numbers interrupt the otherwise empty opening field.
    if quote and re.fullmatch(r'\s*\d+\t\s*', body):
        return 0.9
    if not field:
        if quote:
            if '\\' in token:
                if '\n' in body:
                    return 1.6 if opener == '{' else 0.9
                return 2.8 if opener == '{' else 2.0
            if '\n' in body:
                return 3.6 if opener == '{' else 2.6
            return 1.8 if opener == '{' else 1.3
        if token in ('@', '"@'):
            return 1.6
        if token in ('class', 'internal') and opener == '{':
            return 2.0
    if s == '@' and re.fullmatch(r'\s*\\*"', body):
        return 1.5
    if quote and '\n' in body and body.rstrip().endswith(','):
        return 0.35
    if opener == '[' and text[:k].endswith('#'):
        if token == 'test':
            return 2.1
        if token in ('inline', 'macro'):
            return -1.2
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    value = response(s, recent)
    return (doc, (recent + s)[-96:]), value

