ARTICLES = {'La': 0.90, 'Il': 0.95, 'El': 0.80, 'Le': 0.49, 'ال': 0.93}
DECLARATIONS = {
    'namespace': 1.05, 'public': 0.90, 'package': 0.62,
    'using': 0.62, 'import': 0.42, 'from': 0.48,
    'const': 0.41, 'class': 0.31, '#include': 0.23, '#pragma': 0.52,
}
PRONOUNS = frozenset('i me we us you he him she her it they them'.split())
AUXILIARIES = frozenset(
    'am is are was were be been being have has had having'.split()
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        age, opening, previous, java = 0, '', '', False
    else:
        _, age, opening, previous, java = carry
