            return state, 1.32
        if token in ('#', '•'):
            return state, -0.41
        if token == '<!':
            return state, -0.90
        if token == '$(':
            return state, 0.93
        if token == '<':
            return state, 0.64
        if token == '<|endoftext|>':
            return state, 0.76
        if token == '<|im_start|>':
            return state, -0.042
        if token == 'Title':
            return state, 0.23
        if token == 'The':
            return state, -0.08
        if token.isspace():
            return state, 0.60 if token == '\t' else 0.20
        if len(token) == 1 and token.isascii() and token.isupper():
            return state, 0.26
        return state, 0.08 if token.isascii() else -0.02

    if token == 'import':
        return state, -0.23 if java or previous.rstrip().endswith(';') else 0.03
    if token == '··':
        return state, 0.25
    if token == '․':
        return state, 0.13
    if token in ('://', 'www') or previous.endswith('://'):
        return state, 0.09
    word = token.strip()
    if word.lower() in PRONOUNS:
        return state, -0.014
    if word.lower() in AUXILIARIES:
        return state, -0.01
    if token and not token[0].isspace():
        if word.isalpha():
            attached = bool(previous and previous[-1].islower())
            return state, -0.02 if attached and len(word) <= 4 else -0.006
        return state, 0.005 if '.' in word else -0.004
    return state, 0.0

