CHAT = set('lol lmao rofl btw omg ur thx thanx pls plz'.split())
REDUCED = set('wanna gonna gotta kinda sorta dunno lemme gimme'.split())
NEGATIONS = set('dont didnt doesnt isnt arent wasnt werent wouldnt couldnt '
