    """Primary dictionary senses of 'and so on'; also allow Chinese final 的."""
    if len(word) < 2 or word.isascii():
        return False
    senses = cedict.glosses(word)[:1] + jmdict.glosses(word)[:1]
    if word.endswith('的'):
        senses += cedict.glosses(word[:-1])[:1]
