Apache names, attach/detach forms, and split Massachusetts fragments get
large positive outputs. Short Latin, Cyrillic and Persian fragments depend
on the preceding vowel: a/anch is usually positive; e or Persian ye can
be negative. A short vowel or French participle suffix can complete a
fragment. Whole-word tokens are deliberately treated differently from
fragments. Most other positions get zero.

Only the current and two preceding tokens of the document are inspected.
The constants are rounded training estimates, not exact contextual amplitudes.
"""
import re
import unicodedata

READS = ()
CONSONANT = re.compile(r'ch|sh|[čšșчшхش]')
VOWELS = dict(zip('аеэиіїыоёуюя', 'aeeiiiioouua'))
VOWELS.update({'ا': 'a', 'آ': 'a', 'ی': 'i', 'ي': 'i'})

# Values for (base fragment, extended fragment, consonant starts a token).
SPELLING = {
    'ch': {'a': (1.1, 1.5, 1.6), 'ea': (-1.6, -1.6, 0.0),
           'e': (-0.2, -0.2, -0.65), 'o': (0.0, 0.0, 0.2),
           'u': (0.05, 0.05, 0.25)},
    'sh': {'a': (0.13, 0.13, 0.72), 'e': (-0.75, -0.75, -0.2)},
    'ч': {'a': (0.5, 0.5, 1.1), 'e': (-0.2, -0.2, 0.0)},
    'ш': {'a': (2.1, 0.0, 1.5), 'e': (-2.0, 0.0, 0.0),
          'i': (0.0, 0.0, -0.37)},
    'ش': {'a': (0.0, 0.0, 0.6), 'i': (0.0, 0.0, -2.8)},
    'х': {'a': (0.5, 0.5, 0.2), 'e': (-1.0, -1.0, -3.5)},
}


def unaccent(s):
    return ''.join(c for c in unicodedata.normalize('NFD', s)
                   if not unicodedata.combining(c))


def predict(previous, current):
    word = current.strip().lower()
    text = (previous + current).lower()
    boundary = len(previous)
    for stem in ('apache', 'attach', 'detach'):
        start = text.rfind(stem)
        if start >= 0 and start + len(stem) > boundary:
            if stem == 'apache':
                if current.startswith(('.', '/')):
                    return 16.5
                return 10.8 if stem in current.lower() else 15.5
            if 'ment' in current.lower():
                return 0.5
            if stem not in current.lower():
                return 7.0 if stem == 'attach' else 3.5
            if word.endswith('attach') and not current.startswith(' '):
                return 5.2
            return 3.4
    massach = text.rfind('massach')
    if len(word) <= 4 and massach >= 0 and massach + 7 > boundary:
        return 7.5  # Short ach/ache fragment completing Massachusetts.
    if word == 'anche':  # Italian "also": a common whole-word exception.
        return 2.1
    if word == 'each':
        return 0.12
    if re.fullmatch('[bp]each', word):
        return -2.4 if current.strip()[0].isupper() else -1.4

    hits = list(CONSONANT.finditer(text))
    if not hits:
        return 0.0
    hit = hits[-1]
    after = text[hit.end():]
    before = text[:hit.start()].rstrip('\u200c\u200d')
    nasal = before.endswith(('n', 'н', 'ن'))
    if nasal:
        before = before[:-1]
    vowel = unaccent(VOWELS.get(before[-1:], before[-1:]))
    if vowel == 'a' and before.endswith('ea'):
        vowel = 'ea'
    consonant = hit.group()
    if hit.end() <= boundary:
        # One vowel, or a French participle ending, completing the fragment.
        if boundary - hit.end() > 2:
            return 0.0
        if re.fullmatch('é(?:e)?s?', current.lower()):
            return 3.2 if vowel == 'a' else 1.0
        if (len(current) == 1 and unaccent(current.lower())
                in 'aeiouаеёиіїуыэюя'):
            if before.endswith('at'):
                vowel = 'a'  # The affricate spelling atch.
            if vowel == 'a':
                return {'ch': 1.8, 'ч': 1.4, 'ш': 0.7, 'х': 1.0}.get(
                    consonant, 0.0)
        return 0.0
    if len(after) > 3 or (after and not after.isalpha()):
        return 0.0
    local = unaccent(text[boundary:hit.start()].strip())
    if hit.start() <= boundary:
        phase = 2
    elif re.fullmatch('[aeiouаеэиіїыоёуюя][nн]?', local):
        phase = 1 if after and after[0] in 'aeiouy' else 0
    elif (hit.group() in ('ch', 'č') and len(word) <= 6
          and current.strip()[0].isupper()
          and re.fullmatch('[a-zа-я][aа][nн]?', local)):
        return 0.5
    else:
        return 0.0

    if phase != 2 and consonant == 'ш' and after:
        phase = 1
    consonant = {'č': 'ch', 'š': 'sh', 'ș': 'sh'}.get(consonant, consonant)
    if consonant == 'х' and phase == 2 and before.endswith('ї'):
        return -3.5
    if consonant == 'ch' and nasal and vowel == 'a':
        return 2.7
    values = SPELLING.get(consonant, {}).get(vowel)
    return values[phase] if values else 0.0


def step(carry, prefix, upstream):
    t = prefix.position
    doc = prefix.document_ids[t]
    recent = [prefix.token_bytes[i] for i in range(max(0, t-2), t)
              if prefix.document_ids[i] == doc]
    previous = b''.join(recent).decode('utf8', errors='replace')
    return None, predict(previous, prefix.token_strings[-1])

"""A sparse multilingual lexical detector.

Chinese/Japanese bend and valley characters give negative responses; the
response to 曲 is weaker in music compounds such as 作曲 (compose music).
Small additional rules cover grievance vocabulary and fermentation starter.
Split-byte completions of the Korean readings 곡, 굴, 절 also respond,
but whole Korean syllable tokens do not. Thai ก-based syllables, especially
กับ (with), instead give positive responses. Unrecognized tokens receive zero.
A short byte tail handles split Unicode and resets at document boundaries.
"""

READS = ()
BENDS = {"曲": -5.2, "屈": -4.7, "折": -1.4}
HOLLOWS = {"谷": -2.7, "峡": -4.3, "峽": -4.3,
           "凹": -0.75, "窟": -0.3}
# 曲 also means fermentation starter, as do these koji characters.
KOJI = frozenset("麹麴")
GRIEVANCES = {"苦": -0.9, "枉": -1.6, "冤": -1.1}
KOREAN_READINGS = {"곡": -5.5, "굴": -6.0, "절": -1.8}
MUSIC_PREFIXES = tuple("作名楽樂词詞奏響响题題")


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = b"" if carry is None or carry[0] != doc else carry[1]
    before = previous.decode("utf-8", "replace")
    raw = prefix.token_bytes[-1]
    joined = previous + raw
    token = prefix.token_strings[-1]
    fragment = "\ufffd" in token
    if fragment:
        token = joined.decode("utf-8", "replace")[-1:]
    value = BENDS.get(token, HOLLOWS.get(token,
            GRIEVANCES.get(token, 0.0)))
    if fragment:
        value = KOREAN_READINGS.get(token, value)
    if token == "曲" and before.endswith(MUSIC_PREFIXES):
        value = -2.9
    elif token == "屈" and before.endswith("理"):
        value = -3.3
    elif token in KOJI:
        value = -3.8
    elif token == "曲折":
        value = -2.3
    elif token == "委屈":
        value = -3.5
    elif token in ("三峡", "三峽"):
        value = -2.5
    elif len(token) == 2 and "曲" in token:
        value = -0.65
    elif token in ("山谷", "峡谷", "峽谷"):
        value = -0.7
    if token == "ก":
        value = 0.4
    elif token == "ค":
        value = 1.5 if before.endswith("ก็") else 0.05
    elif token == "ับ":
        value = 3.6 if before.endswith("ก") else (
            1.4 if before.endswith("ล") else 0.45)
    elif token == "ือ":
        value = 1.5 if before.endswith("ค") else 0.0
    elif token == "็" and before.endswith("ก"):
        value = 1.0
    elif token == "ัด" and before.endswith("ก"):
        value = 1.8
    return (doc, joined[-64:]), value

"""Approximate a WHAT/spelling feature with local, causal text rules.

Question-introducing contexts give negative values; copulas, object-taking
verbs and prepositions often give positive values. WordNet supplies verb
inflections and a weak default for unfamiliar verbs. Short split spellings
like W + AT and WH + ATS also produce negative responses. The remaining
rules cover related interrogatives, LaTeX's hat, and two startup/typographic
responses. Unrecognized cases stay near zero. This is not a full parser.
"""
import re
import wordnet

READS = ()

# Small grammatical/semantic classes of words immediately before 'what'.
CONTEXTS = (
    (3.1, {'do', 'get', 'not', 'accomplish', 'achieve', 'deliver'}),
    (1.4, {'be', "that's", 'that’s', "here's", 'here’s'}),
    (1.8, {'in', 'with', 'into', 'between', 'beyond', 'through', 'from'}),
    (0.9, {'of', 'on', 'to'}),
    (-0.3, {'at', 'for', 'as', 'by', 'over'}),
    (1.5, {'exactly', 'precisely', 'only'}),
    (-0.25, {'know', 'understand', 'determine', 'decide', 'remember',
             'out', 'about'}),
    (-0.85, {'see', 'check', 'sure', 'unclear', 'imagine', 'consider',
             'idea', 'explain', 'clarify', 'tell'}),
    (-1.9, {'wonder', 'say', 'matter'}),
)


def after_word(left):
    parts = re.findall(r"[A-Za-z]+(?:['’][A-Za-z]+)?|[^\sA-Za-z]", left)
    while parts and parts[-1] in {'”', '’', '"'}:
        parts.pop()
    if not parts or not parts[-1][0].isalpha():
        return -3.6
    previous = parts[-1]
    w = previous.lower()
    if w in {'but', 'so'}:
        return -5.1
    if w in {'then', 'because', 'or', 'yet', 'wait', 'hey'}:
        return -3.1
    if w == 'and':
        return -4.6 if previous[0].isupper() else -2.8
    roots = set(wordnet.base_forms(w, 'verb')) | {w}
    if roots & {'think', 'guess', 'that'}:
        return -2.4
    for value, words in CONTEXTS:
        if roots & words:
            return value
    return 0.7 if 'verb' in wordnet.parts_of_speech(w) else -0.3


def fragment(left, token):
    """Recognize short what-like spellings across a token boundary."""
    if not left or not token or not token[0].isalpha():
        return None
    end, s = left.lower(), token.lower()
    if end.endswith('wh'):
        if s.startswith(('at', 'ad')):
            return -12.5
        if s == 'ar':
            return -6.5
        if s in {'al', 'als', 'aling', 'ak', 'aa'}:
            return -5.1
        if s == 'it':
            return -3.5
    elif end.endswith('w'):
        if s == 'tf':  # WTF, an interrogative/exclamatory abbreviation
            return -12.0
        if re.fullmatch(r'at(?:s|t|ter|ters)?', s):
            return -6.8
        if s.startswith('at'):
            return -2.5
    if re.fullmatch(r'at(?:s|t)?', s):
        if end.endswith(('u', 'q')):
            return -4.5
        if end.endswith('h') and not end.endswith(('ph', 'ch')):
            return -2.7
    if s == 'hat':
        if end.endswith('\\'):
            return 0.52  # LaTeX accent, not a word continuation
        if end[-1].isalpha():
            return -2.6
    if s == 'heat' and end.endswith('w'):
        return -4.2
    if re.search(r'(?:^|[^a-z])s?qu$', end):
        if re.fullmatch(r'at(?:s|t|ter|ters)?', s):
            return -7.0
    if re.search(r'(?:^|[^a-z])qu$', end):
        if s in {'el', 'els', 'elles'}:
            return -5.5
        if s == 'elle':
            return -1.5
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    left = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    bare = token.strip(' \t\n\r"“”(')
    w = bare.lower()
    value = -0.002
    if w == 'what':
        if not left:
            value = 0.62 if bare[0].isupper() else 1.03
            if token == ' What':
                value = 2.21
        elif bare[0].isupper() or not token.startswith(' ') or left.endswith('\n'):
            value = -3.45
        else:
            value = after_word(left)
    elif w == 'whats':
        value = -5.5
    elif w == 'whatever':
        value = -0.7 if bare[0].isupper() else 0.4
    elif w in {'wat', 'watts', 'quat', 'uat'}:
        value = -4.7
    elif w == 'watt':
        value = -3.2
    elif w in {'quel', 'quelle', 'quelles', 'quels', 'qué', 'què', 'hvad'}:
        continuation = not token.startswith(' ') and left and left[-1].isalpha()
        value = -3.5 if w in {'qué', 'què', 'hvad'} else -2.3
        if continuation:
            value = -0.4
        if left.rstrip().endswith(','):
            value = -6.0
    elif w in {'welche', 'welcher', 'welches', 'wel', 'welk'}:
        value = -1.7
    elif w == 'wie':
        value = -0.7
    elif bare in {'Was', 'Что'}:
        value = -1.2
    elif w in {'qu', 'que'}:
        if bare[0].isupper():
            value = -1.1
        elif re.search(r'\bce$', left):
            value = -0.8
        elif token == ' qu':
            value = -1.5 if left.rstrip().endswith((',', '.', '?', ':')) else -0.1
    elif w in {'any', 'such', 'other'}:
        value = -0.13
    elif w == 'package' and not left:
        value = 4.0
    elif token == '··':
        value = 1.16
    split = fragment(left, token)
    return (doc, (left + token)[-120:]), value if split is None else split

"""Approximate the component's main formatting responses.

Negative pulses mark the newline between messages and the next role name
(user more strongly than assistant). Tool-block openings have smaller pulses.
There is also a rough, shape-based offset on document-initial text, a Title:
header pattern, and a positive response to repeated middle-dot padding.
All state resets at document boundaries.
"""
READS = ()

MARKUP = {
    '<|im_start|>': -0.09,
    '<|endoftext|>': -0.02,
    '<tool_call>': -0.28,
    '<tool_response>': -0.15,
    '</tool_call>': -0.10,
    '</tool_response>': -0.10,
    '<think>': 0.11,
    '</think>': 0.08,
}
TOOL_ENDS = ('</tool_call>', '</tool_response>')


def opening_offset(token):
    """A coarse estimate of the otherwise token-specific opening offset."""
    text = token.strip()
    if token == '<|im_start|>':
        return -0.151
    if token == 'Title':
        return 1.90
    if not text:
        return 0.29
    if text.isdigit():
        return 0.45
    if token.startswith(' '):
        return 0.33 if text.isalpha() else 0.41
    if text.isupper():
        return 0.39
    if text.istitle():
        return -0.025
    return 0.27 if text.islower() else 0.34


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before, position, starts = '', '', 0, 0
        chat_opening = token == '<|im_start|>'
    else:
        _, previous, before, position, starts, chat_opening = carry
        position += 1
    if token == '<|im_start|>':
        starts += 1

    value = MARKUP.get(token, 0.0)
    if position == 0:
        value = opening_offset(token)
    elif previous == '<|im_start|>':
        if token == 'user':
            value = -1.865 if position == 1 else -2.284
        elif token == 'assistant':
            first_reply = chat_opening and starts == 2
            value = -1.581 if first_reply else -1.366
            if position == 1:
                value = -1.918
        elif token == 'system':
            value = -1.64
    elif position == 1 and previous == 'Title' and token == ':':
        value = -4.42
    elif token == '\n' and previous == '<|im_end|>':
        if before in TOOL_ENDS:
            value = -1.475
        else:
            value = -0.98 if before.rstrip().endswith(('?', '!')) else -0.87
    elif token == '<|im_end|>':
        value = -0.01 if previous in TOOL_ENDS else 0.14
    elif token.isspace():
        if previous == '<tool_call>':
            value = -0.60
        elif previous == '<tool_response>':
            value = -0.70
        elif previous == '<think>':
            value = -0.19
        elif previous == '</think>':
            value = -0.27
        elif previous == 'user' and before == '<|im_start|>':
            value = -0.102 if position == 2 else 0.08
    if len(token) >= 2 and set(token) == {'·'}:
        if position == 0 or (previous and set(previous) == {'·'}):
            value = 1.42

    return (doc, token, previous, position, starts, chat_opening), value

