"""layers.1.mlp.down_proj:5718: a large negative spike on each document's first token.

The component is almost silent except at a document's first token, where the model has no
earlier context to attend to. There it writes a large negative value, whose size depends on
what kind of token it is:
  - a token made only of punctuation, symbols or whitespace (".\\n\\n", "?", " :"): about -79;
  - a word that starts with a space (" test", " content"): about -112;
  - any other token (words without a leading space, code, subwords): about -99.
Everywhere else the component is a small negative drift, about -1.1.

A document start is a position where the document id changes, or the row's first token.
The per-token values are class means over the whole vocabulary, run through the model
with each token alone at position 0.
"""
import unicodedata

READS = ()

START_BY_CLASS = {"nonword": -79.0, "spaceword": -112.0, "word": -99.0}
REST_VALUE = -1.1


def token_class(text):
    if not text.strip() or not any(unicodedata.category(c)[0] in "LN" for c in text):
        return "nonword"
    if text[0] == " " and all(unicodedata.category(c)[0] == "L" for c in text[1:]):
        return "spaceword"
    return "word"


def step(carry, prefix, upstream):
    docs = prefix.document_ids
    if len(docs) == 1 or docs[-1] != docs[-2]:
        value = START_BY_CLASS[token_class(prefix.token_strings[-1])]
    else:
        value = REST_VALUE
    return None, float(value)

