"""A split-off word-ending detector.

Respond to English inflections and derivational endings attached to a stem,
using dictionary morphology and the stem's part of speech. Familiar stems
with uncommon derived forms get a larger response. Recognize several common
Cyrillic case/number and Arabic plural endings too. Middle-dot-only
prefixes are inhibited; other tokens normally receive zero.
"""
import re
from functools import lru_cache
import wordnet
from wordfreq import zipf_frequency

READS = ()
ENGLISH_ENDINGS = {
    's', 'es', 'ed', 'd', 'ing', 'er', 'ers', 'or', 'est',
    'ly', 'ness', 'less', 'ful', 'able', 'ible', 'al', 'ic',
    'ism', 'ist', 'ity', 'ize', 'ise', 'en', 'ous', 'ive',
    'ment', 'e', 'y', 'hood',
}
CYRILLIC_ENDINGS = set('а я у ю ы и е ом ем ов ев ам ям ах ях ами ями ой ий'.split())

@lru_cache(maxsize=50000)
def lexicon(word):
    return wordnet.parts_of_speech(word), zipf_frequency(word, 'en')

@lru_cache(maxsize=50000)
def base_forms(word):
    return wordnet.base_forms(word)


def ending_response(token, stem, previous):
    ending = token.lower()
    if not stem:
        return 0.6 if ending == 's' and previous[-1:].isdigit() else 0.0
    if ending in CYRILLIC_ENDINGS:
        if len(stem) < 3 or stem.isupper():
            return 0.0
        if ending in {'ы', 'ов', 'ами', 'ями'}:
            return 0.7
        return 0.4 if ending in {'а', 'ом', 'ах'} else 0.15
    if ending == 'ات':  # Arabic feminine plural.
        return 0.4
    if ending in {'-wise', '-most', '-ed'}:
        return 0.9

    doubled = (len(ending) > 1 and ending[0] == stem[-1].lower()
               and ending[0] not in 'aeiou'
               and ending[1:] in {'ed', 'ing', 'er', 'est', 'en', 'y'})
    if doubled:
        ending = ending[1:]
    if ending not in ENGLISH_ENDINGS:
        return 0.0

    base = stem.lower()
    whole = (stem + token).lower()
    parts, familiar = lexicon(base)
    _, derived = lexicon(whole)
    valid = base in base_forms(whole)
    noun = 'noun' in parts
    adjective = 'adjective' in parts
    verb = 'verb' in parts
    capitals = stem.isupper()

    if ending == 's':
        value = (0.7 + 0.1 * (familiar - derived) + 0.2 * valid
                 + 0.4 * adjective + 0.6 * capitals)
    elif ending == 'es':
        sibilant = base.endswith(('s', 'x', 'z', 'ch', 'sh'))
        value = 1.2 * sibilant + 0.85 * valid
    elif ending in {'ed', 'ing'}:
        value = (0.6 + 0.5 * valid + 0.6 * doubled + 0.3 * noun
                 - 0.15 * derived - 0.25 * capitals)
        if not valid and len(stem) <= 3:
            value = 0.0
    elif ending == 'd':
        value = 0.7 * valid
    elif ending == 'er':
        value = (0.2 + 0.25 * noun + 0.2 * verb + 0.25 * doubled
                 - 0.35 * capitals)
        if len(stem) <= 3 and not parts:
            value = 0.0
    elif ending in {'ers', 'or', 'est'}:
        value = 0.05 + 0.1 * noun + 0.3 * valid + 0.1 * doubled
    elif ending == 'ly':
        value = (0.25 + 0.6 * adjective + 0.05 * familiar
                 - 0.11 * derived - 0.3 * capitals)
    elif ending in {'ness', 'ful', 'hood'}:
        value = 0.35 + 0.18 * (familiar - derived) + 0.4 * adjective
    elif ending in {'able', 'ible'}:
        value = 0.3 + 0.45 * noun - 0.07 * derived - 0.2 * capitals
    elif ending == 'e' and len(stem) > 2 and base.endswith('a') and valid:
        value = 3.6  # Latin plurals, e.g. formula + e.
    elif ending == 'en':
        value = 0.1 + 0.35 * doubled + 0.1 * noun - 0.2 * capitals
    elif ending == 'y':
        value = 0.1 + 0.2 * noun + 0.5 * doubled - 0.15 * capitals
    elif ending in {'al', 'ism', 'ist', 'ity', 'ment'}:
        value = 0.05 + 0.2 * noun + 0.15 * adjective
        if parts:
            value += 0.15 * max(0, familiar - derived - 1)
    else:
        value = 0.1 * bool(parts)
    return max(0.0, min(4.0, value))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        stem, previous, dots_only = '', '', True
    else:
        _, stem, previous, dots_only = carry
    token = prefix.token_strings[-1]
    value = ending_response(token, stem, previous)
    dots_only = dots_only and bool(token) and set(token) == {'·'}
    if dots_only and len(token) >= 2:
        value = -2.9
    tail = re.search(r'[^\W\d_]+$', token)
    if tail:
        stem = (stem + token if tail.start() == 0 else tail.group())[-80:]
    else:
        stem = ''
    return (doc, stem, token, dots_only), value

