READS = ()


def startup(token):
    """Approximate the exceptional response before ordinary context exists."""
    text = token.strip()
    if token.startswith('\t'):
        return -4.7 if token.isspace() else -7.0
    if len(token) > 1 and token[0] in '/_.-' and token[1].isalpha():
        # Attached path, identifier, member-access, and hyphenated fragments.
        return {'/': 10.0, '_': 6.0, '.': 6.0, '-': 7.5}[token[0]]
    if token.startswith((',', '，', '、')):
        return 2.9
    if token.startswith((':', ';')):
        return 2.1
    if token.startswith(')') or (token.startswith('(') and len(token) > 1):
        return 2.5
    if token.startswith('$'):
        return -5.4
    if token.startswith('`'):
        return -4.6
    if token.startswith(('“', '‘')):
        return -3.2
    if token.startswith(('%', '％')):
        return 6.5
    if token.startswith('^'):
        return 4.2
    if len(text) >= 2 and not text.strip('·'):
        return 8.1  # Decorative middle-dot leaders.
    if token.startswith(('//', '/*')):
        return -0.8
    if token.startswith('\\'):
        return -1.0
    if token.startswith('<|'):
        return -0.6
    if '\n\n' in token and text:
        return 1.6
    if text.isdecimal():
        return -0.22
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        initial_run, previous = True, ''
    else:
        _, previous, previous_bytes, initial_run = carry
        initial_run = initial_run and prefix.token_bytes[-1] == previous_bytes

    value = 0.0
    if initial_run:
        value = startup(token)
    else:
        word = previous.strip().lower()
        if word == 'let':
            if token == ' me':
                value = -0.56 if previous.strip() == 'let' else -0.66
            elif token == ' us':
                value = -0.4 if previous.strip() == 'let' else -0.56
            elif token in ("'s", '’s'):
                value = -0.26
        elif word in ('i', 'we'):
            if token in (' will', ' shall', "'ll", '’ll'):
                value = -0.4 if word == 'i' else -0.22
    return (document, token, prefix.token_bytes[-1], initial_run), value

