"""Layer 1, MLP down-projection, component 5721: a document-start detector.

In plain terms:
- Inside running text this component is almost silent. Its large values happen at the
  first token of each document, where the model has no earlier text to look at (attention
  is reset at a document boundary). There, the value depends on what kind of token it is:
  punctuation that normally continues a sentence or identifier ('_', ',', '-', '/', ')',
  ':', '.') pushes it positive; indentation, '$', curly quotes, '<' and '#' push it
  negative; ordinary word-start tokens sit near zero, a little higher when capitalised
  after a space.
- Two narrow in-text cases: 'me' right after 'Let' or 'let' is mildly negative, and a long
  run of the '··' token (visible-space dots) is strongly positive.

The numbers are averages over sampled training data, so this predicts the typical value
and not each token's exact value. Most of the explained variance is at document starts.
"""

READS = ()

# Mean activation at a document's first token, by its first character.
PUNCT = {
    "_": 5.0, "^": 4.2, "-": 3.2, ",": 3.0, "/": 2.8, "，": 2.4, "=": 2.4, ")": 2.6,
    ":": 2.2, "(": 2.0, ".": 1.8, ";": 1.7, "}": 1.2, "[": 1.1, "?": 1.3, "*": 1.2,
    "!": 1.2, "。": 1.2, "'": 0.9, '"': 0.6, "#": -0.6, "<": -0.7, "\\": -1.1,
    "|": -0.5, "{": -1.7, "“": -3.1, "$": -4.7, "\t": -5.1,
}
PUNCT_DEFAULT = 1.0


def first_token_value(token):
    """Activation at a document's first token, from the token's text alone."""
    if not token:
        return 0.0
    first = token[0]
    if first in PUNCT:
        return PUNCT[first]
    if first.isspace():
        return 0.1 if first in "\r\n" else -0.5
    if first.isdigit():
        return -0.2
    if first.isalpha():
        spaced = first == " " and len(token) > 1
        letter = token[1] if spaced else first
        if spaced:
            return 0.9 if letter.isupper() else 0.2
        return -0.2 if first.isupper() else 0.3
    return PUNCT_DEFAULT


