    """carry: the length of the current run of '··' tokens and the last token (or None)."""
    token = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        run = 0
        previous = None
    else:
        run, previous = carry
    if token == "··":
        run += 1
    else:
        run = 0
    carry = (run, token)
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, first_token_value(token)
    if token == "··" and run >= 8:
        return carry, 8.0
    if token == "me" or token == " me":
        if previous in (" Let", "Let", " let"):
            return carry, -0.65
    return carry, 0.0

