        return 1.5 if word == 'The' else 5.0
    if lower == 'package':
        return 12.0 if spaced else 23.4
    if lower in {'test', 'tests'}:
        return 13.0 if spaced else 24.0
    if lower in PERSONAL_PRONOUNS:
        if spaced:
            return 3.8
        return 13.8 if word == 'I' else 6.5
    if lower in DEMONSTRATIVES:
        return 3.5 if spaced else 7.0
    if lower in FUNCTION_WORDS:
        if spaced:
            return -0.7 if lower in {'of', 'on', 'by', 'from', 'with'} else 0.9
