READS = ()

NEWLINE_VALUE = -0.2     # tokens with a line break
ASCII_WORD_VALUE = -7.1  # lowercase ASCII words
CAPITAL_WORD_VALUE = -7.6  # ASCII words with an uppercase letter
OTHER_VALUE = -4.8       # punctuation, digits, non-ASCII, spaces


def starts_document(prefix):
    """True at a row's first token and wherever the document id changes."""
    if prefix.position == 0:
        return True
    return prefix.document_ids[-1] != prefix.document_ids[-2]


def step(carry, prefix, upstream):
    if not starts_document(prefix):
        return None, 0.0
    token = prefix.token_strings[-1]
    word = token.strip()
    if "\n" in token or "\r" in token:
        value = NEWLINE_VALUE
    elif word.isascii() and word.isalpha():
        value = CAPITAL_WORD_VALUE if any(c.isupper() for c in word) else ASCII_WORD_VALUE
    else:
        value = OTHER_VALUE
    return None, float(value)

