import unicodedata as ud

READS = ()
# Vowels and hard/soft signs: characters excluded from consonant clusters.
VOWELS_AND_SIGNS = set('аеёиоуыэюяіїєъь')
GREEK_VOWELS = set('αεηιουω')


def script(ch, name):
    return bool(ch) and name in ud.name(ch[0], '')


