    initial = previous.startswith(' ') or position == 1
    stem = previous.strip()

    if position == 0 and token == 'Title':
        value = -1.09
    elif position == 1 and previous == 'Title' and token == ':':
        value = 20.37
    elif token == 'ـ':  # Arabic tatweel: a connecting stroke, not a letter.
        value = -12.0 if initial else -3.8
    elif token and ud.category(token[0]) == 'Mn' and script(token[0], 'ARABIC'):
        value = -4.0 if initial else -0.4
    elif raw == b'\xd6' and stem and script(stem[-1], 'HEBREW'):
