                    value = 1.9
                elif prev == 'в':
                    value = 2.2 if ch not in 'лрнй' else 0.5
                elif prev not in VOWELS_AND_SIGNS:
                    value = 0.45
        elif script(ch, 'GREEK') and script(prev, 'GREEK'):
            base = ud.normalize('NFD', ch)[0]
            if base == 'ι':
                value = -1.4
            elif ch == 'έ':
                value = -1.0
            elif base == 'η':
                value = -0.3
            elif ch in 'μκσ' and prev in GREEK_VOWELS:
