"""A rough detector of trailing English qualifications, not a full parser.

Negative examples: 'five each', 'purposes only', 'A and B respectively',
'rights reserved', 'x squared', and 'in particular'. Auxiliary-led uses
are usually weaker. Additive 'I too' is negative; excessive 'is too' is
positive. Other tokens default to zero. WordNet supplies a rough noun
class; a short, document-local text tail joins words split over tokens.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
AUX = set('am is are was were be been being has have had'.split())
DET = set('''a an the this that these those my your his her its our their
any some no every'''.split())
NUMBERS = set('''one two three four five six seven eight nine ten eleven
twelve thirteen fourteen fifteen sixteen seventeen eighteen nineteen twenty
thirty forty fifty sixty seventy eighty ninety hundred thousand million
few several'''.split())
FUNCTION = AUX | DET | NUMBERS | set('''to of in on at by for from with as
into over under near behind between among through after before until beside
within without than and or but if then so now when where which who what how
not can could will would shall should may might must do does did i you he
she it we they me him us them all each both'''.split())
# Common fixed adverbial phrases and postposed qualifications.
PHRASES = {
    'as well': -0.85, 'in general': -2.4, 'in particular': -2.3,
    'at large': -2.8, 'in short': -0.55, 'for short': -1.5,
    'on average': -1.4, 'for example': -0.65, 'in front': 0.9,
    'up front': -2.0, 'reason why': -1.6, 'reasons why': -1.6,
    'rights reserved': -4.2, 'right reserved': -4.2,
    'pun intended': -6.0, 'as intended': -1.6,
}
PARTICIPLES = {'included', 'involved', 'combined'}
QUALIFIERS = set('''respectively alike squared cubed too only each well
particular general total inclusive alone'''.split()) | PARTICIPLES
QUALIFIERS |= {phrase.split()[-1] for phrase in PHRASES}

@lru_cache(maxsize=8192)
def nominal(w):
    if not w or w.lower() in FUNCTION:
        return False
    if w.isdigit() or (w.isupper() and len(w) <= 4):
        return True
    pos = wordnet.parts_of_speech(w)
    return 'noun' in pos and ('verb' not in pos or
        any(b != w.lower() for b in wordnet.base_forms(w, 'noun')) or
        w.lower() in {'people', 'men', 'women', 'children', 'staff'})


def response(before, word):
    w = word.lower()
    if w not in QUALIFIERS:
        return 0.0
    previous = re.search(r'([A-Za-z]+|[0-9]+)\s*$', before)
    raw = previous.group(1) if previous else ''
    p = raw.lower()
    noun = nominal(raw) or p in NUMBERS
    if raw and p not in FUNCTION and 'noun' in wordnet.parts_of_speech(p):
        # A numeral followed by a noun: 'one set', even if 'set' is also a verb.
        left = before[:previous.start()].split()
        numeral = left and (left[-1].isdigit() or left[-1].lower() in NUMBERS)
        noun = noun or bool(numeral)
    comma = before.rstrip().endswith(',')
    initial = not before.strip() or bool(re.search(r'[.!?\n]\s*$', before))
    quantity = bool(re.search(r'\d', before[-45:])) or bool(
        set(re.findall(r'[a-z]+', before[-45:].lower())) & NUMBERS)
    phrase = p + ' ' + w
    if phrase in PHRASES:
        value = PHRASES[phrase]
        # Clause-opening 'In general' is weaker than a trailing 'in general'.
        if raw == 'In' and w in {'general', 'particular'}:
            value = -1.2
        if raw == 'For' and w == 'example':
            value = 0.0
        return value
    if w == 'respectively':
        return -0.7 if p in AUX or p in {'will', 'would', 'can'} else -4.1
    if w == 'alike':
        return 0.4 if p in AUX else (-4.8 if noun else -1.3)
    if w in {'squared', 'cubed'}:
        if p in DET or p in {'we', 'when'}:
            return 0.0
        return -0.9 if p in AUX else (-2.8 if w == 'squared' else -4.2)
    if w == 'too':
        if before.rstrip().lower().endswith('own way'):
            return -1.5
        excess = {'s', 're', 'm', 'not', 'never', 'way', 'far', 'bit',
                  'little', 'much', 'getting', 'become', 'seems', 't', 'all'}
        if p in AUX or p in excess:
            return 2.0
        if p in {'i', 'me', 'you', 'he', 'she', 'we', 'they', 'us', 'them'}:
            return -3.2
        proper_name = raw.istitle() and not wordnet.parts_of_speech(raw)
        if comma or (proper_name and p not in FUNCTION and not initial):
            return -2.3
        return -1.2 if noun else 0.25
    if w == 'only':
        if p in AUX or p in {'s', 're'}:
            return 0.6
        if p == 'purposes':
            return -4.5
        return -1.8 if noun else -0.3
    if w == 'each':
        if initial or word[0].isupper():
            return 0.03
        amount = noun or before.rstrip().endswith(('%', '"'))
        return -2.8 if quantity and amount else (-0.25 if comma else 0.0)
    if w == 'total':
        if p == 'in' or raw.isdigit():
            return -1.0
        return -0.6 if noun and quantity else 0.05
    if w == 'inclusive':
        return -4.1 if noun or comma or p == 'both' else -1.6
    if w == 'alone':
        return 0.2 if p in AUX or p in {'not', 'let', 'stand', 'less'} else -1.8
    if w in PARTICIPLES:
        active = {'have', 'has', 'had', 'we', 'they', 'he', 'she', 'which'}
        if p in DET or p in active:
            return 0.0
        if w == 'combined':
            return -2.2 if noun else -0.7
        return -1.0 if noun else (-0.6 if w == 'included' else -0.25)
    plain = {'well', 'particular', 'general', 'example', 'front'}
    return 0.05 if w in plain else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    text = tail + s
    word_ending = s and s[-1].isascii() and s[-1].isalpha()
    match = re.search(r'[A-Za-z]+$', text) if word_ending else None
    value = response(text[:match.start()], match.group()) if match else 0.0
    return (doc, text[-120:]), float(value)

