"""Layer-1 MLP down-projection component 5732, as a document-start detector.

Its activation is near zero inside a document. It is large only at a document's first
token, and at the second token in one template case. The first-token value depends on
which kind of token opens the document: code and keyword openers push it negative, a
capitalised word with no leading space pushes it slightly negative, and a word with a
leading space (mid-sentence text) pushes it slightly positive. The one large
second-token case is the colon in a document that opens "Title:", which gives about -4.
"""

READS = ()

CODE_OPENERS = {"import", "package", "using", "//", "const", "namespace", "module", "<?php"}


def first_token_value(s):
    if s in CODE_OPENERS:
        return -0.5
    if s[:1].isdigit():
        return -0.15
    if s[:1].isupper():
        return -0.1
    if s[:1] == " ":
        return 0.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or doc != carry[1]:
        pos = 0
    else:
        pos = carry[0] + 1
    tok = prefix.token_strings[-1]
    if pos == 0:
        value = first_token_value(tok)
    elif pos == 1 and prefix.token_strings[-2] == "Title" and tok == ":":
        value = -4.18
    else:
        value = 0.0
    return (pos, doc), float(value)

