        return -1.7678  # A leading decorative run of middle dots.
    if s == r'\t':
        return -2.1947
    if s == '//\n':
        return -3.5112
    if s in ('\\', ' \\'):
        return 1.5104
    if s == '%':
        return -1.1545
    if s == '#':
        return -0.3646
    if s in ('package', 'class'):
        return -1.1576
    if s in ('using', 'import'):
        return -0.5288
    if s == 'var':
        return 1.7483
    if word.lower() in ('not', 'no', 'never'):
        return -0.9251
    if s in ('Is', 'Are'):
        return -0.9555
    if word.lower() in ('my', 'your', 'our', 'his', 'her', 'their'):
        return -0.7871
    if word.isdigit():
        return 0.0229
    if s.isspace():
        return -0.1576
    if s.startswith(' ') and word.isalpha():
        return -0.2091
    if len(s) == 1 and s.isalpha() and s.isupper():
        return 0.0749
    if word and not any(c.isalnum() for c in word):
        return -0.1582
    return -0.0699


