    elif s == ':' and previous == 'Title' and position == 1:
        value = -1.6387
    elif s == ':' and previous == ' Thread' and position < 4:
        value = -1.0
    elif s == ' on' and previous == 'Published' and position == 1:
        value = 1.1634
