The main negative response is to o (also os) inside an uncommon word prefix
with at most two vowel letters. Uppercase fragments in short words respond
more strongly. Common English words and prefixes with three vowel letters
are mostly quiet (apart from the uppercase rule).
Transliteration applies the same spelling tests to other alphabets. These
are coarse averages, not a complete account of the component's variation.
"""
import re
from functools import lru_cache

from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=16000)
def romanize(text):
    return anyascii(text).lower()


@lru_cache(maxsize=16000)
def english_frequency(word):
    return zipf_frequency(word, 'en')


@lru_cache(maxsize=4000)
def romance_frequency(word):
    return max(zipf_frequency(word, lang) for lang in ('es', 'pt', 'it'))


def response(fragment, word, starts_word, uppercase):
    if uppercase:
        if starts_word:
            return -0.13
        if len(word) > 4:
            return -0.25
        # Very frequent Romance fragments are less emphatic.
        return -1.42 if romance_frequency(fragment) >= 6.5 else -2.33

    frequency = english_frequency(word)
    vowels = sum(letter in 'aeiou' for letter in word)
    if frequency >= 4.5 or vowels >= 3:
        return 0.0
    if starts_word:
        return -0.19 if fragment.endswith('o') else 0.0
    if frequency < 0.75:
        return -0.20
    vowel_groups = len(re.findall('[aeiouy]+', fragment))
    return -1.31 if vowel_groups >= 2 else -0.76


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    match = re.search(r'[^\W\d_]+$', before + token)
    after = match.group()[-32:] if match else ''
