        return carry, -1.8 if before.isupper() and token == '.O' else -1.0

    fragment = romanize(token.strip())
    if not fragment.isalpha() or not fragment.endswith(('o', 'os')):
        return carry, 0.0
    starts_word = not before or token != token.lstrip()
    word = ('' if starts_word else romanize(before)) + fragment
    value = response(fragment, word, starts_word, token.strip().isupper())
    return carry, value

