READS = ()

LIFT_WORDS = {"lift", "lifts", "lifting", "lifted"}
LUCK_WORDS = {"luck"}
TRUCK_WORDS = {"truck", "trucks"}
LUM_PIECES = {"lum", "olum", "plum", "llum", "ulum", "imum", "lund", "lumen"}
UM_PIECES = {"um", "und", "üm", "umen", "ume", "ums", "ulu", "ul"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if cur == "吊":
        return None, 8.0
    if cur in LIFT_WORDS or cur in LUCK_WORDS or cur in TRUCK_WORDS:
        return None, 2.0
    if cur == "ift" and prev.endswith("l"):
        return None, 2.0
    if cur in LUM_PIECES:
        return None, -3.0
    if prev.endswith("l") and cur in UM_PIECES:
        return None, -4.0
    return None, 0.0

