        return 1.5
    parts = wordnet.parts_of_speech(low)
    if s.startswith(' '):
        if low in {'a', 'to'}:
            return 5.8
        if low in {'and', 'in', 'is', 'at', 'so', 'be'}:
            return 3.0
        if len(w) <= 2 and w.isupper():
