        return 4.6 if parts & CONTENT_POS else 3.9
    if w == 'The':
        return 1.3
    if low in QUESTIONS:
        return 8.6 if low in {'how', 'which'} else 6.5
    if low in {
        'is', 'are', 'will', 'can', 'could', 'should', 'would', 'does', 'do'
    }:
        return 5.1
    if low in {'this', 'that', 'these', 'those', 'there', 'they'}:
        return 4.7
    if low in {'we', 'you', 'a', 'an', 'it'}:
        return 3.8
    if low in {'one', 'each', 'any', 'all', 'some', 'many', 'few', 'every'}:
        return 5.5
    if low in {'he', 'in', 'on', 'to'}:
        return {'he': 2.5, 'in': 2.6, 'on': 1.2, 'to': 5.3}[low]
    if w.istitle():
        return 3.8 if parts & CONTENT_POS else 2.9
    if w.isupper():
