def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        return (doc, s[-200:], 0), opener(s)
    _, tail, age = carry
    w = s.strip()
    at_line = bool(LINE_START.search(tail))
    previous_word = tail.split()[-1:]
    after_modifier = bool(previous_word and previous_word[0] in MODIFIERS)
    value = 0.0
    if w == 'import':
        java = bool(JAVA_IMPORT.search(tail))
        value = -4.8 if at_line and s == 'import' and java else -0.6
    elif w in MODIFIERS and (at_line or after_modifier):
        value = -1.8
    elif w in DECLARATIONS and (at_line or after_modifier):
        value = -0.9
    elif w in {'using', 'use'} and at_line:
        php = '<?php' in tail or PHP_IMPORT.search(tail)
        value = -5.5 if php else -2.0
    elif w in {'package', 'export', 'extern'} and at_line:
        value = -0.9
    elif w == 'void' and (at_line or after_modifier):
        value = -1.0
    elif w == 'from' and at_line:
        value = -2.1 if s == 'from' else -1.0
    elif w.startswith('//'):
        value = -0.55
    elif w == '#':
        value = -0.4
    elif w in ('self', 'this') and at_line:
        value = -0.7
