        if tail.endswith('githubusercontent'):
            value = -4.8
        elif tail.endswith('github') and not tail.endswith('.github'):
            value = -4.1
        elif tail.endswith('bitbucket'):
            value = -2.5
    if age == 0 and tail == '1' and s == '2':
        value = 10.5
    if s.isspace() and tail.isspace():
        value = opener(s)
    return (doc, (tail+s)[-200:], age+1), value

programs.haiku:
"""Layer 1, MLP down-projection component 5744.

What it does, in plain terms:
  1. At the first token of a document, it reads the token's kind. Words in any writing
     system score high (English lowercase words after a space highest), digits and CJK
     score mildly positive, and blank space, line breaks, brackets, quotes and symbol runs
     score negative.
  2. Inside code, it goes strongly negative on declaration keywords that open a line:
     `import` after a line ending in ';' (Java, C#, Go-style), `using`, `public`, `private`,
     `protected`, `static`, `from`, `func`, `def`. A `.com` right after `github` (a URL) is
     also strongly negative. Everywhere else it is 0.

It predicts the activation (x.V_c)*||U_c|| directly, so no model is needed to run it.
"""

import re
import unicodedata

READS = ()

# Declaration keywords that open a line, and what the component reads there.
LINE_OPENERS = {"import": -5.0, "using": -3.4, "public": -2.3, "private": -1.9,
                "protected": -2.0, "static": -1.4, "from": -1.8, "func": -1.0, "def": -0.8}


def is_cjk(ch):
    return unicodedata.name(ch, "").startswith(("CJK", "HIRAGANA", "KATAKANA", "HANGUL"))


def doc_start_value(tok):
    """Activation for the first token of a document, by the kind of token it is."""
    core = tok.lstrip(" ")
    if core == "" or "\n" in tok or "\r" in tok or "\t" in tok:
        return -3.0                                    # blank space and line breaks
    if core[0] in "([{\"'“‘`":
        return -2.5                                    # opening brackets and quotes
    if any(is_cjk(c) for c in core):
        return 1.5                                     # Chinese, Japanese, Korean
    if re.fullmatch(r"[0-9]+", core):
        return 1.2                                     # numbers
    if any(c.isalpha() for c in core):                 # words in any alphabet
        if tok.startswith(" "):
            return 4.0 if core.islower() else 3.5      # a word after a space
        return 2.7
    if len(set(tok)) == 1 and len(tok) > 1:
        return -1.6                                    # runs like "****" or "----"
    return -0.5 if not tok.startswith(" ") else 0.0    # other punctuation and symbols


def line_context(toks):
    """(opens a line, the previous non-blank text ends in ';') for the token being read."""
    i = len(toks) - 2
    while i >= 0 and toks[i].strip(" \t") == "":       # skip indentation
        i -= 1
    opens = i < 0 or "\n" in toks[i]
    k = i
    while k >= 0 and toks[k].strip() == "":            # the last non-blank text
        k -= 1
    return opens, k >= 0 and toks[k].rstrip().endswith(";")


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    tok = toks[-1]
    if len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, float(doc_start_value(tok))       # first token of a document
    if tok == ".com" and toks[-2].endswith("github"):
        return None, -5.0                              # the .com of a github.com URL
    word = tok.lstrip(" \t")
    if word in LINE_OPENERS:
        opens, after_semicolon = line_context(toks)
        if opens:
            if word == "import" and not after_semicolon:
                return None, -0.6                      # Python-style import: nearly neutral
            return None, float(LINE_OPENERS[word])
    return None, 0.0

programs.sol:
"""A sparse predictor for date boundaries and URL separators.

Positive pulses mark a month following a day, date punctuation or whitespace
where a year commonly follows, and HTTP(S) ://. Repeated middle dots also get
a positive value. "Of" is negative after relation nouns (country, place,
instance, member), and more weakly in other phrases. Other month tokens get
a small negative value; unrecognized positions get zero. Only recent text is
kept, and it is reset at document boundaries. No future year is inspected.
"""
import calendar
import re

# English and common French, Spanish, Italian and German month names.
FULL_MONTHS = {w.lower() for w in calendar.month_name[1:]}
FULL_MONTHS.update('''janvier février fevrier mars avril mai juin juillet août
aout septembre octobre novembre décembre decembre enero febrero marzo abril
mayo junio julio agosto septiembre octubre noviembre diciembre gennaio
febbraio maggio giugno luglio settembre ottobre dicembre januar februar märz
maerz juni juli oktober dezember'''.split())
ABBREVIATIONS = {w[:3] for w in FULL_MONTHS}
ABBREVIATIONS.update(('sept', 'janv', 'févr', 'fevr', 'juil'))
MONTH_WORDS = FULL_MONTHS | ABBREVIATIONS
ENGLISH_MONTHS = set(calendar.month_name[1:]) | set(calendar.month_abbr[1:])
MONTH = ('(?:' + '|'.join(sorted(FULL_MONTHS, key=len, reverse=True)) +
         '|(?:' + '|'.join(sorted(ABBREVIATIONS, key=len, reverse=True)) + r')\.?)')
DAY = r'\d{1,2}(?:st|nd|rd|th|er|°)?'
US_DATE = re.compile(r'\b' + MONTH + r'\s+' + DAY + r'$', re.I)
EU_DATE = re.compile(
    r'\b' + DAY + r'\.?\s+(?:(?:of|de|del)\s+)?' + MONTH + r'$', re.I)
SLASH_DATE = re.compile(r'(?<![\w/])\d{1,2}/\d{1,2}/$')
LAST_WORD = re.compile(r'([^\W\d_]+)\.?$')


def predict(before, token):
    # Literal escaped whitespace occurs in quoted documents and logs.
    before = before.replace('\\n', '\n').replace('\\r', '\r').replace('\\t', '\t')
    if '://' in token:
        if before.endswith('https'):
            return 0.93
        if before.endswith('http'):
            return 1.33
        return 0.13
    if token and set(token) == {'·'} and len(token) > 1:
        return 2.79
    if token == ',' and US_DATE.search(before.rstrip()):
        return 1.24
    if token == " '" and US_DATE.search(before):
        return 2.46
    if token == ' ':
        if before.endswith(',') and US_DATE.search(before[:-1].rstrip()):
            return 1.67
        if EU_DATE.search(before):
            return 1.36
        if before.endswith((' de', ' del')):
            if EU_DATE.search(before.rsplit(' ', 1)[0]):
                return 1.36
        if US_DATE.search(before.rstrip('.')):
            return 1.34
    if token in (' de', ' del') and EU_DATE.search(before):
        return 1.3
    if any(c.isalpha() for c in token):
        m = LAST_WORD.search(before + token)
        if m and m.group(1).lower() in MONTH_WORDS:
            if EU_DATE.search(before + token):
                return 0.71
            if token.strip() in ENGLISH_MONTHS:
                return -0.13
    if token == '/' and SLASH_DATE.search(before + token):
        return 1.41
    if token == ' of':
        m = re.search(r'([A-Za-z]+)$', before)
        word = m.group(1) if m else ''
        if word.lower() in {'country', 'place', 'instance', 'member'}:
            return {'country': -0.64, 'place': -0.53,
                    'instance': -0.46, 'member': -0.31}[word.lower()]
        if word and word[0].isupper():
            return -0.08
        if word == 'type' and re.search(r'(?:->|—|:|\|)\s*type$', before):
            return -0.34
        return -0.01
    return 0.0


READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(before, token)
    return (doc, (before + token)[-120:]), value

"""Local phrase rules for human effort, communication, and time as a resource.

The strongest negative cases are familiar human-activity phrases: body
language, human error, eye contact, attention to detail, and personal or
leisure time. Duration/degree descriptions (long time, easy way) instead
get positive values. Most tokens get zero. These rules approximate only
this lexical portion of the component; they also handle document starts
and chat delimiters. History is limited to the last 100 characters.
"""
import wordnet
from functools import lru_cache

READS = ()
HUMAN = set(('human personal social interpersonal mental physical body public '
             'community customer user manual ordinary self').split())
PERSONAL = set('my your his her our their its me you us them'.split())
SCALAR = set(('good great bad poor best worst high low large small long short '
              'hard easy deep rich strong weak full wide narrow big major '
              'minor positive negative').split())
SOCIAL = set(('interaction interact communication cooperation collaboration '
              'participation involvement coordination teamwork companionship '
              'assistance collaborative').split())
EFFORT = set(('effort attention focus concentration precision precise '
              'improvement strength skill supervision intervention').split())

