    words = recent.lower().split()
    if s == 'time':
        value = -0.17
        if p in {'long', 'short', 'hard'}:
            value += 1.08
        elif p in SCALAR:
            value += 0.54
        if p in {'free', 'alone', 'family'}:
            value -= 2.91
        if p in {'spare', 'leisure'}:
            value -= 1.78
        if p == 'quality':
            value -= 2.11
        if p in PERSONAL:
            value -= 1.27
        if p in {'more', 'much', 'less', 'little', 'valuable', 'precious', 'allotted'}:
            value -= 0.68
        if set(words[-5:]).intersection({
                'spend', 'spending', 'spent', 'wasting', 'wasted', 'save',
                'saving', 'investing', 'devote', 'managing'}):
            value -= 1.46
    if s == 'language':
        value -= 0.115
        if p == 'body':
            value -= 4.46
        elif p in {'natural', 'human', 'plain'}:
            value -= 1.71
        elif p in {'negative', 'explicit', 'respectful', 'sloppy',
                   'everyday', 'precise', 'own'}:
            value -= 1.26
    if s in {'error', 'errors'}:
        value -= 0.04
        if p == 'human':
            value -= 4.27
        elif p == 'pilot':
            value -= 2.43
        elif p == 'and' and 'trial' in words:
