        value -= 0.29 + (1.23 if p in HUMAN else 0)
    if EFFORT.intersection(forms(s)):
        value -= 0.19 + (0.66 if p in HUMAN else 0)
    if s in {'attention', 'precision', 'precise', 'supervision'}:
        value -= 0.36
    if s == 'intervention' and p == 'human':
        value -= 2.83
    if s == 'to' and p == 'attention':
        value -= 0.95
    if s in {'detail', 'details'} and p == 'to' and 'attention' in words:
        value -= 3.57
    if s in {'effort', 'efforts'} and p == 'and':
        value -= 1.84
    if s in {'service', 'services', 'resource', 'resources', 'development'}:
        if p in HUMAN:
            value -= 1.26
    if s in {'help', 'aid', 'assistance'}:
        if p in {'professional', 'for', 'seek', 'seeking', 'sought', 'need', 'needs'}:
            value -= 0.68
    if s in {'contact', 'touch', 'privacy'}:
        value -= 0.12
        if s == 'contact' and p == 'eye':
            value -= 4.42
        elif p in {'close', 'human', 'personal'}:
            value -= 0.83
    if s in {'space', 'spaces'}:
        value -= 0.24
        if p in {'more', 'green', 'outdoor', 'rack', 'open', 'public', 'personal'}:
            value -= 1.07
    if s == 'paper':
        value -= 0.23
        if p in {'of', 'on', 'and', 'glassine', 'toilet', 'tissue'}:
            value -= 0.58
        if p == 'and' and 'pen' in words:
            value -= 0.78
    if s in {'amount', 'way', 'sense', 'place'} and p in SCALAR:
        value += 0.54
    if s in {'rate', 'level', 'effect', 'future', 'history', 'picture', 'diagram'}:
        value += 0.09
    if s in {'of', 'in', 'with', 'to', 'for', 'on', 'off'} and p == 'time':
        value -= 0.10 + (0.38 if s in {'in', 'with', 'off'} else 0)
