    if p in {'do', 'move'} and token.startswith(' |'):
        return -3.72
    if p in {'public', 'private', 'protected'} and s.startswith('$'):
        return -2.32
    # Closing code quotes, then line breaks after keywords.
    if token == '`' and p in KEYWORDS:
        if p in TYPES:
            return -1.53
        if p in {'static', 'public', 'private', 'class', 'void'}:
            return -3.53
        if p in {'if', 'for', 'while'}:
            return -3.51
        return -1.49
    if token.isspace() and '\n' in token:
        if p in SQL:
            return -2.8
        if p in {'declare', 'static', 'Try'}:
            return -3.16
        if p in LINE_END:
            return LINE_END[p]
        if p in {'fn', 'pub', 'struct', 'const', 'mut', 'self', 'done', 'bool'}:
            return -1.0
        if p in CONTROL:
            return -0.56
    return 0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same = carry is not None and carry[0] == doc
    previous = carry[1] if same else ''
    count = carry[2] if same else 0
    token = prefix.token_strings[-1]
    value = response(previous, token, count == 1)
    return (doc, token, count + 1), float(value)

programs.haiku:
"""Layer-1 MLP down_proj component 5757: a negative detector for the first token of a
declared name or type in code.

The component is mostly negative and large on the sigil or opening token that comes
right after a declaring word, where a variable or type name is about to be written:
Perl `my $x` / `my @x`, SQL `SET @x`, Rust `let mut x` and `&mut`, Go `make([]...)`
and `map[string]`, C/Java `static`/`public`/`int`/`class` followed by `{`, a backtick
or `[`, Rust `impl<'a>`. The program predicts -3.2 there, the average over such cases.

Weaker negative cases: a flag after a shell command (`grep -n`, `cat -n`, `rm -f`,
about -1.2); a newline or colon right after a block word (`else`, `try`, `begin`,
`do`, about -2.2); the `.mod` and `.sum` parts of Go's go.mod and go.sum filenames
(-1.5). Mildly positive (+1.2) on the brace in LaTeX `\\ref{` / `\\label{` / `\\cite{`.
Everywhere else it predicts 0, which is close to its typical near-zero value.

Only the previous token and the current token are read, so it is causal.
"""

READS = ()

DECLARING_WORDS = {
    "my", "SET", "let", "static", "const", "map", "make", "impl", "public", "private",
    "class", "void", "int", "byte", "using", "struct", "&", "(&", "(map",
}
NAME_START = {" @", "@", " $", "$", " \\$", "\\$", " `", "`", " mut", "mut", "<'",
              "[string", " ([]", "([]", "[]", " []", " {", " {\\", "{"}
SHELL_WORDS = {"grep", "cat", "ls", "rm", "sed", "tail", "make", "@@"}
BLOCK_WORDS = {"else", "try", "begin", "do"}
BLOCK_START = {"\n", ":\n"}
LABEL_WORDS = {"ref", "label", "cite"}


def step(carry, prefix, upstream):
    if len(prefix) < 2:
        return None, 0.0
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip()
    if prev in DECLARING_WORDS and cur in NAME_START:
        value = -3.2
    elif cur in {" -", "-"} and prev in SHELL_WORDS:
        value = -1.2
    elif cur in BLOCK_START and prev in BLOCK_WORDS:
        value = -2.2
    elif cur in {".mod", ".sum"}:
        value = -1.5
    elif cur in {"{", " {"} and prev in LABEL_WORDS:
        value = 1.2
    else:
        value = 0.0
    return None, value

programs.sol:
"""Approximate the component with spelling and short character context.

Negative rules cover Vietnamese open syllables ending in horned vowels,
especially the locative ở, and several Thai vowel/tone combinations.
Vietnamese adjustments use the vowel, tone, and initial consonant spelling.
Positive offsets cover middle dots, Thai leading o, and document starts;
small boundary/control-token offsets handle </think> and the null character.
UTF-8 fragments are joined, and the last eight characters supply Thai context.
Other lexical and longer-context effects are deliberately left near zero.
"""
import codecs
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    if initial:
        before, pending = '', b''
    else:
        _, before, pending = carry
    data = pending + prefix.token_bytes[-1]
    token, used = codecs.utf_8_decode(data, 'replace', False)
    pending = data[used:]
    s = token.strip().lower()
    value = -0.001

    if s and set(s) == {'·'}:
        value += 1.02 * min(len(s), 2) / 2

    if s and s.isalpha():
        last = unicodedata.normalize('NFD', s[-1])
        if '\u031b' in last:  # the horn on Vietnamese ơ and ư
            decomposed = unicodedata.normalize('NFD', s)
            base = ''.join(c for c in decomposed
                           if not unicodedata.combining(c))
            value -= 0.7
            if last[0] == 'o':
                value += 0.4
            if len(base) == 1:
                value -= 0.7
            if base.startswith('c'):
                value -= 0.4
            if base.startswith('s'):
                value -= 0.25
            if '\u0309' in last:  # hook-above tone
                value -= 1.0
            if '\u0323' in last:  # dot-below tone
                value += 0.7
            if last == 'o\u031b':
                value -= 0.7
            if token[:1].isspace() and s == 'ở':
                value -= 2.0

    # Thai sara uee, optionally joined to a tone or to o-ang.
    if s and 'ื' in s and set(s) <= set('ื่้๊๋อ'):
        value -= 1.35
        if any(c in s for c in '่้๊๋'):
            value -= 1.05
        if 'เ' in before[-2:]:
            value -= 1.4
        if s == 'ือ':
            value += 0.75
    if s in ('่', '้', '๊', '๋'):
        value -= 0.35
        if before.endswith('ื'):
            value -= 2.4
    if s == 'อ' and before.endswith(('ื', 'ื่', 'ื้', 'ื๊', 'ื๋')):
        value -= 1.5
    if s == 'ี่' and 'เ' in before[-2:]:
        value -= 1.8
    if s == 'ั':
        value -= 0.45
    if s == 'โ':
        value += 0.5
    if pending == b'\xe0\xb9':  # incomplete Thai vowel/tone mark
        value -= 0.55
    if s == 'ํ':
        value -= 4.0

    if initial:
        value += 0.23
    if s == '</think>':
        value += 0.2
    if s == '\x00':
        value -= 0.15
    return (doc, (before + token)[-8:], pending), float(value)

"""Recognize introductions to selection and ordering criteria.

The strongest negative cases are sorting/grouping/filtering 'by' a property,
SQL WHERE, and field-based retrieval method names. Smaller rules cover English
based-on/according-to phrases, possessives, and lambda/mapping notation.
A separate positive rule handles a document-opening Title: heading.
Only a short trailing text buffer is needed; documents reset that buffer.
"""
import re

READS = ()

def predict(token, before):
    word = token.strip()
    low = word.lower()
    # Split code's camelCase as well as ordinary words.
    context = re.sub(r'([a-z])([A-Z])', r'\1 \2', before[-100:])
    words = re.findall(r'[A-Za-z]+', context.lower())
    recent = words[-6:]
    last = words[-1] if words else ''
    sorting = any(w in ('sort', 'sorted', 'sorting', 'sorts') for w in recent)
    grouping = last in ('group', 'partition') or any(
        w in ('grouped', 'grouping', 'partitioned', 'partitioning') for w in recent)
    ordering = any(w in ('ordered', 'ordering', 'ranked', 'ranking',
                         'arranged', 'arranging') for w in recent)
    filtering = last == 'filter' or any(
        w in ('filtered', 'filtering', 'filters') for w in recent)
    retrieval = any(w.startswith(('search', 'find', 'query', 'lookup',
                                  'retriev', 'select', 'index', 'get'))
                    for w in recent)
    selection = sorting or grouping or ordering or filtering or retrieval
    if low == 'by':
        if last in ('order', 'partition'):
            return -6.91
        if (word == 'By' and not token[0].isspace()
                and before and before[-1].isalnum()):
            return -4.06
        if sorting:
            return -9.42
        if grouping:
            return -6.45
        if ordering:
            return -2.12
        if filtering:
            return -8.41
        if last in ('query', 'search', 'get', 'find', 'filter', 'list', 'match'):
            return -4.32
        if retrieval:
            return -0.7
        if any(w in ('weighted', 'stratified', 'organized', 'organize', 'varies',
                     'vary', 'listed', 'extract', 'matches', 'distribution',
                     'broken', 'breaks', 'clustered') for w in recent):
            return -2.86
        if any(w.startswith(('classif', 'categor', 'identif', 'distinguish'))
               for w in recent):
            return -1.31
        if not token[0].isspace() and before and before[-1].isalnum():
            return -0.24
        return -0.04
    if re.fullmatch(r'[_/]by', word, re.I):
        if 'creativecommons' in before:
            return -0.04
        return -9.0 if sorting else -5.07
    if re.search(r'(?i:get|find|search|query|select|delete)By(?=$|[A-Z_])', word):
        if word.endswith('By'):
            return -8.0 if 'find' in low else -5.98
        return -4.25
    if re.search(r'(Order|Group|Sort)By', word):
        return -3.0
    if re.fullmatch(r'By[A-Z][a-zA-Z]*', word):
        return -3.07
    if low == 'where':
        if word.isupper():
            return -4.19
        if re.search(r'(?i)select\b.{0,90}\bfrom\b', before):
            return -5.96
        if last in ('rows', 'columns', 'records', 'items', 'values', 'pairs', 'elements'):
            return -1.6
        return -0.56 if selection else 0.01
    if low == 'of' and last in ('basis', 'terms', 'order'):
        return {'basis': -1.77, 'terms': -0.72, 'order': -1.33}[last]
    if low == 'on' and last in ('based', 'depending'):
        return -1.56 if selection else -0.61
    if low == 'to' and last == 'according':
        if selection:
            return -1.86
        return -0.03 if before.rstrip().endswith('According') else -1.02
    if low == 'their':
        if last in ('by', 'on', 'to', 'and'):
            return {'by': -1.64, 'on': -0.53, 'to': -0.63, 'and': -0.21}[last]
        return -0.16
    if low == 'all':
        if last in ('get', 'retrieve', 'retrieves'):
            return -1.75
        return -0.56 if retrieval else -0.04
    if low in ('that', 'who', 'whose', 'with'):
        if last in ('rows', 'keys', 'paths', 'values', 'columns', 'fields',
                    'records', 'books', 'members', 'files', 'items', 'lines'):
            return -0.51
    if low == 'according' and selection:
        return -0.89
    if low in ('grep', 'filter') or low == '.filter':
        return -0.55
    if re.fullmatch(r'\.?(get|find)All', word):
        return -2.07
    if word == '=>':
        return -0.41
    if word == ':' and 'lambda' in words[-5:]:
        return -0.63
    if word == ':' and (before == 'Title'
                        or before.endswith('<|endoftext|>Title')):
        return 6.08
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    value = predict(token, before)
    return (document, (before + token)[-160:]), value

programs.haiku:
"""A negative feature on the word that introduces the criterion by which things are
sorted, grouped, filtered, ranked or looked up, i.e. the preposition or keyword that
opens a selection/ordering spec. Examples: "sorted BY", "GROUP BY", "ORDER BY", "filter
BY", SQL "FROM t WHERE", "based ON", "on the BASIS OF", "in the ORDER OF", "according TO",
"classified BY", camel-case lookups such as "findById", "getBy", "ByName", and URL segments
"/by-query". Strongest after sorting/grouping verbs, weaker after other selection verbs,
and near zero elsewhere (e.g. "conducted by", "by the way", most "of"/"to"/"their")."""
import re

READS = ()

SORT_WORDS = {"sort", "sorted", "sorting", "sorts", "order", "ordered", "ordering", "orders",
              "group", "grouped", "grouping", "groups", "query", "queried", "filter",
              "filtered", "filtering", "partition", "neighbours", "neighbors"}
SELECT_STEMS = ("weigh", "index", "search", "select", "specif", "organi", "classif", "rank",
                "arrang", "separat", "categor", "cluster", "stratif", "compar",
                "identif", "distinguish", "differentiat")
BASED_WORDS = {"based", "according", "depending"}
BASIS_NOUNS = {"basis", "order", "terms"}
SQL_WORDS = {"from", "select", "update", "delete", "join"}
LOOKUP_NAME = re.compile(r"[a-z_/.]By(?=[A-Z_]|$)|_by(?![a-z])|/by(?![a-z])|^By[A-Z]|^_By")


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].strip()
    w = raw.lower()
    docs = prefix.document_ids
    prev = []
    for j in range(max(0, len(docs) - 6), len(docs) - 1):
        if docs[j] == docs[-1]:
            prev.append(prefix.token_strings[j].strip().lower())
    last = prev[-1] if prev else ""
    value = 0.0
    if LOOKUP_NAME.search(raw):
        value = -3.5
    elif w == "where":
        if raw == "WHERE" or any(x in SQL_WORDS for x in prev[-3:]):
            value = -3.5
    elif w == "by":
        if last in ("order", "group", "partition", "sort") or any(x in SORT_WORDS for x in prev[-2:]):
            value = -7.0
        elif any(x.startswith(SELECT_STEMS) for x in prev[-5:]):
            value = -2.0
    elif w == "their" and last == "by":
        value = -2.0
    elif w in ("on", "to", "of") and last in BASED_WORDS:
        value = -1.0
    elif w == "of" and last in BASIS_NOUNS:
        value = -1.0
    elif w == "=>" and any(x in ("filter", "map", "find", "some", "every") for x in prev):
        value = -2.0
    return carry, value
